import type {
  AgentArtifact, AgentNamespace, FreeStorageConfig, SaveOptions, StorageStatus,
} from "./types";
import {
  DEFAULT_POLICY, LS_CONFIG, LOCAL_MAX_ARTIFACTS,
} from "./constants";
import {
  uid, estimateBytes, saveLocalArtifact, getLocalArtifact,
  listLocalByAgent, deleteLocalArtifact, getLocalStats, clearAllLocal,
} from "./indexed-store";
import {
  loadManifestFromLs, saveManifestToLs, createEmptyManifest,
  uploadArtifactToGist, updateManifestIndex, syncManifestFromGist,
} from "./gist-vault";
import { cloudVaultPreferred } from "@/lib/cloud-vault-client";

export function loadConfig(): FreeStorageConfig {
  try {
    const raw = localStorage.getItem(LS_CONFIG);
    if (raw) {
      const parsed = JSON.parse(raw) as FreeStorageConfig;
      return {
        policy: parsed.policy ?? DEFAULT_POLICY,
        githubToken: parsed.githubToken,
        gistId: parsed.gistId ?? loadManifestFromLs()?.gistId,
        allowSupabaseAgentWrites: parsed.allowSupabaseAgentWrites ?? false,
      };
    }
  } catch { /* defaults */ }
  return {
    policy: DEFAULT_POLICY,
    allowSupabaseAgentWrites: false,
    gistId: loadManifestFromLs()?.gistId,
  };
}

export function saveConfig(cfg: Partial<FreeStorageConfig>): FreeStorageConfig {
  const next = { ...loadConfig(), ...cfg };
  const toStore = { ...next };
  localStorage.setItem(LS_CONFIG, JSON.stringify(toStore));
  if (next.gistId) {
    const m = loadManifestFromLs() ?? createEmptyManifest();
    m.gistId = next.gistId;
    saveManifestToLs(m);
  }
  return next;
}

export function shouldWriteSupabase(): boolean {
  const cfg = loadConfig();
  return cfg.allowSupabaseAgentWrites && cfg.policy === "supabase-legacy";
}

/** Primary API — save any agent output without touching Supabase. */
export async function saveAgentArtifact<T>(opts: {
  agent: AgentNamespace;
  kind: string;
  title: string;
  data: T;
  id?: string;
  options?: SaveOptions;
}): Promise<AgentArtifact<T>> {
  const cfg = loadConfig();
  const now = new Date().toISOString();
  const id = opts.id ?? uid();
  const artifact: AgentArtifact<T> = {
    id,
    agent: opts.agent,
    kind: opts.kind,
    title: opts.title,
    createdAt: now,
    updatedAt: now,
    sizeBytes: estimateBytes(opts.data),
    data: opts.data,
  };

  await saveLocalArtifact(artifact);

  let manifest = loadManifestFromLs() ?? createEmptyManifest();
  manifest = updateManifestIndex(manifest, artifact);
  saveManifestToLs(manifest);

  if (cloudVaultPreferred()) {
    const { cloudSaveArtifact } = await import("@/lib/cloud-vault-client");
    await cloudSaveArtifact({
      agent: opts.agent,
      kind: opts.kind,
      title: opts.title,
      data: opts.data,
      id,
    });
  }

  const useGist =
    !opts.options?.localOnly &&
    cfg.githubToken &&
    (cfg.policy === "gist-sync" || cfg.policy === "free-first");

  if (useGist && cfg.githubToken) {
    const result = await uploadArtifactToGist(cfg.githubToken, manifest, artifact);
    if (result) {
      manifest = updateManifestIndex(result.manifest, artifact);
      saveManifestToLs(manifest);
      saveConfig({ gistId: result.gistId });
    }
  }

  return artifact;
}

export async function getAgentArtifact<T>(id: string): Promise<AgentArtifact<T> | null> {
  return getLocalArtifact<T>(id);
}

export async function listAgentArtifacts<T>(agent: AgentNamespace): Promise<AgentArtifact<T>[]> {
  return listLocalByAgent<T>(agent);
}

export async function deleteAgentArtifact(id: string): Promise<void> {
  await deleteLocalArtifact(id);
  const manifest = loadManifestFromLs();
  if (!manifest) return;
  for (const agent of Object.keys(manifest.index) as AgentNamespace[]) {
    manifest.index[agent] = (manifest.index[agent] ?? []).filter((x) => x !== id);
  }
  saveManifestToLs(manifest);
}

export async function getStorageStatus(): Promise<StorageStatus> {
  const cfg = loadConfig();
  const stats = await getLocalStats();
  const manifest = loadManifestFromLs();
  return {
    policy: cfg.policy,
    localCount: stats.count,
    localBytes: stats.bytes,
    gistConnected: Boolean(cfg.githubToken),
    gistId: cfg.gistId ?? manifest?.gistId,
    gistBytes: manifest?.gistBytes ?? 0,
    supabaseWritesEnabled: shouldWriteSupabase(),
    agents: stats.byAgent as StorageStatus["agents"],
  };
}

export async function syncFromGist(): Promise<{ pulled: number; error?: string }> {
  const cfg = loadConfig();
  if (!cfg.githubToken || !cfg.gistId) {
    return { pulled: 0, error: "Connect GitHub Gist first" };
  }

  const manifest = await syncManifestFromGist(cfg.githubToken, cfg.gistId);
  if (!manifest) return { pulled: 0, error: "Could not read gist vault" };

  let pulled = 0;
  for (const [agent, ids] of Object.entries(manifest.index)) {
    for (const id of ids ?? []) {
      const existing = await getLocalArtifact(id);
      if (existing) continue;
      const fileName = `${agent}__${id.replace(/-/g, "").slice(0, 12)}.json`;
      const { pullFromGist } = await import("./gist-vault");
      const artifact = await pullFromGist(cfg.githubToken!, cfg.gistId!, fileName);
      if (artifact) {
        await saveLocalArtifact(artifact);
        pulled++;
      }
    }
  }
  return { pulled };
}

export async function clearFreeStorage(): Promise<number> {
  localStorage.removeItem(LS_VAULT_MANIFEST);
  return clearAllLocal();
}

export { LOCAL_MAX_ARTIFACTS };
