import { triggerFeedIngest } from "@/lib/feed-api-client";

/** Custom event — pages update React state / query cache only (never window.location.reload). */
export const BACKGROUND_REFRESH_EVENT = "threatlens:background-refresh";
/** UI refresh interval — was 10s (too aggressive with Turso feed-api). */
export const BACKGROUND_REFRESH_MS = 60_000;

let ingestTick = 0;
let ingestRunning = false;

/** Queue-based ingest — runs at most once per 5 minutes from the browser. */
export function runBackgroundIngest(): void {
  ingestTick++;
  if (ingestRunning || ingestTick % 5 !== 0) return;
  ingestRunning = true;
  void triggerFeedIngest().finally(() => { ingestRunning = false; });
}

export function dispatchBackgroundRefresh(): void {
  window.dispatchEvent(new CustomEvent(BACKGROUND_REFRESH_EVENT));
}
