/**
 * Auth seam — Clerk handles login; Supabase handles data via JWT template "supabase".
 */
import { useUser, useClerk } from "@clerk/clerk-react";
import { getRuntimeConfig } from "@/lib/runtime-config";

export const SUPABASE_JWT_TEMPLATE = "supabase";

declare global {
  interface Window {
    Clerk?: {
      user?: {
        id: string;
        publicMetadata?: Record<string, unknown>;
        primaryEmailAddress?: { emailAddress?: string };
      } | null;
      session?: { getToken: (opts?: { template?: string }) => Promise<string | null> };
      signOut?: () => Promise<void>;
    };
  }
}

export function currentUserId(): string | null {
  const u = window.Clerk?.user;
  if (!u) return null;
  return (u.publicMetadata?.supabaseUserId as string | undefined) ?? u.id;
}

export function currentUserEmail(): string | null {
  return window.Clerk?.user?.primaryEmailAddress?.emailAddress ?? null;
}

export function isSignedIn(): boolean {
  return !!window.Clerk?.user;
}

export async function getAuthToken(): Promise<string | null> {
  try {
    return (await window.Clerk?.session?.getToken({ template: SUPABASE_JWT_TEMPLATE })) ?? null;
  } catch {
    return null;
  }
}

function decodeJwtPayload(token: string): Record<string, unknown> | null {
  try {
    const part = token.split(".")[1];
    if (!part) return null;
    const padded = part.replace(/-/g, "+").replace(/_/g, "/");
    return JSON.parse(atob(padded)) as Record<string, unknown>;
  } catch {
    return null;
  }
}

/** Clerk JWT that Supabase PostgREST accepts (role=authenticated). Null → anon key. */
export async function getSupabaseAccessToken(): Promise<string | null> {
  const token = await getAuthToken();
  if (!token) return null;
  const payload = decodeJwtPayload(token);
  if (payload?.role === "authenticated") return token;
  return null;
}

export function anonAuthHeaders(): Record<string, string> {
  const cfg = getRuntimeConfig();
  return { Authorization: `Bearer ${cfg.supabasePublishableKey}`, apikey: cfg.supabasePublishableKey };
}

export async function authHeaders(): Promise<Record<string, string>> {
  const token = await getSupabaseAccessToken();
  if (token) {
    const cfg = getRuntimeConfig();
    return { Authorization: `Bearer ${token}`, apikey: cfg.supabasePublishableKey };
  }
  return anonAuthHeaders();
}

export async function signOut(): Promise<void> {
  try {
    await window.Clerk?.signOut?.();
  } catch {
    /* no-op */
  }
}

export { useUser, useClerk };
