import { useCallback, useEffect, useState } from "react";
import { getRuntimeConfig } from "@/lib/runtime-config";
import { anonAuthHeaders } from "@/lib/auth-adapter";
import type { LimitCheck, ServiceHealth } from "@/lib/platform-limits";
import { worstStatus } from "@/lib/platform-limits";

export type PlatformHealth = {
  overall: ServiceHealth | "healthy" | "degraded";
  siteWillRun: boolean;
  checks: LimitCheck[];
  liveMode?: {
    feeds: string;
    retention_days: number;
    storage_target_mb: number;
  };
  neverStop?: {
    frontend: string;
    feeds_fallback: string[];
    agents_fallback: string[];
  };
};

export function usePlatformHealth(pollMs = 300_000) {
  const [health, setHealth] = useState<PlatformHealth | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    const cfg = getRuntimeConfig();
    if (cfg.missingSupabaseConfig) {
      setHealth({
        overall: "ok",
        siteWillRun: true,
        checks: [{ service: "frontend", status: "ok", message: "Static SPA — always available" }],
      });
      setLoading(false);
      return;
    }

    try {
      const hdrs = anonAuthHeaders();
      const res = await fetch(`${cfg.supabaseUrl}/functions/v1/platform-guardian`, {
        headers: hdrs,
      });
      if (res.ok) {
        const data = await res.json();
        setHealth({
          overall: data.overall === "healthy" ? "ok" : data.overall,
          siteWillRun: data.site_will_run !== false,
          checks: data.checks ?? [],
          liveMode: data.live_mode,
          neverStop: data.never_stop,
        });
      }
    } catch {
      setHealth({
        overall: "warn",
        siteWillRun: true,
        checks: [{ service: "api", status: "warn", message: "Guardian unreachable — static site still works" }],
      });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
    const t = setInterval(refresh, pollMs);
    return () => clearInterval(t);
  }, [refresh, pollMs]);

  return { health, loading, refresh, worst: health ? worstStatus(health.checks) : "unknown" };
}
