export function routeSegment(workspaceRoot: string, route: string): string {
  const path = route.split("?")[0];
  if (workspaceRoot === "/") return path.replace(/^\//, "") || "";
  if (path.startsWith(workspaceRoot + "/")) {
    return path.slice(workspaceRoot.length + 1);
  }
  return path.replace(/^\//, "");
}

export function toWorkspaceToolRoute(workspaceRoot: string, legacyPath: string): string {
  const [path, query] = legacyPath.split("?");
  if (workspaceRoot === "/") return legacyPath;
  if (path.startsWith(workspaceRoot)) return legacyPath;
  const segment = path.replace(/^\//, "");
  const base = `${workspaceRoot}/${segment}`;
  return query ? `${base}?${query}` : base;
}

