function buildNavGroups(division: CompanyDivision, root: string): WorkspaceNavGroup[] {
  if (division.id === "red-team") {
    return buildOffensiveNavGroups(root);
  }

  const icon = MODULE_ICONS[division.icon] ?? Shield;
  const liveTools = division.tools.filter((t) => t.live);

  const home: WorkspaceNavGroup = {
    label: "Home",
    items: [
      { title: "Platform Hub", url: "/hub", icon: LayoutGrid, adminOnly: true },
      ...(root !== "/"
        ? [{ title: "Threat Intel", url: "/", icon: Shield, badge: "CTI" }]
        : []),
      { title: "Dashboard", url: root, icon: Home },
    ],
  };

  const modules: WorkspaceNavGroup = {
    label: "Modules",
    items: liveTools.map((t) => ({
      title: t.label,
      url: t.route,
      icon: toolIcon(t, division),
      adminOnly: ADMIN_ONLY_SEGMENTS.has(routeSegment(root, t.route)),
    })),
  };

  const platform: WorkspaceNavGroup = {
    label: "Platform",
    items: [
      { title: "Settings", url: "/engineering/settings", icon: Settings },
      { title: "Admin Console", url: "/engineering/admin", icon: LayoutDashboard, adminOnly: true },
    ],
  };

  return [home, modules, platform];
}

function buildRoutes(division: CompanyDivision, root: string): WorkspaceRouteDef[] {
  const routes = division.tools
    .filter((t) => t.live)
    .map((t) => {
      const segment = routeSegment(root, t.route);
      return {
        segment,
        adminOnly: ADMIN_ONLY_SEGMENTS.has(segment),
      };
    });

  if (division.id === "red-team") {
    routes.push({ segment: "ops-center" });
  }

  return routes;
}

export function buildWorkspaceConfig(divisionId: string): WorkspaceConfig | null {
  const division = getDivision(divisionId);
  if (!division) return null;
  const root = division.workspaceRoute ?? WORKSPACE_ROOTS[divisionId];
  if (!root || root === "/") return null;

  const theme = CATEGORY_THEMES[division.category] ?? CATEGORY_THEMES.operations;
  const icon = MODULE_ICONS[division.icon] ?? Shield;

  return {
    divisionId,
    root,
    title: division.title,
    tagline: division.tagline,
    subtitle: division.category.replace(/-/g, " "),
    icon,
    gradient: division.gradient,
    theme,
    navGroups: buildNavGroups(division, root),
    routes: buildRoutes(division, root),
    adminOnly: division.adminOnly,
  };
}

export function getAllWorkspaceConfigs(): WorkspaceConfig[] {
  return COMPANY_DIVISIONS
    .map((d) => buildWorkspaceConfig(d.id))
    .filter((c): c is WorkspaceConfig => c !== null);
}

export function getWorkspaceByRoot(pathname: string): WorkspaceConfig | null {
  const configs = getAllWorkspaceConfigs();
  const match = configs
    .filter((c) => pathname === c.root || pathname.startsWith(c.root + "/"))
    .sort((a, b) => b.root.length - a.root.length)[0];
  return match ?? null;
}
