import { useState } from "react";
import { ArrowRight, ChevronDown } from "lucide-react";
import {
  FLOW_TABS,
  type FlowStep,
  type FlowTabId,
} from "@/lib/landing-content";

const TONE: Record<NonNullable<FlowStep["tone"]>, string> = {
  violet: "from-violet-500/20 to-violet-600/10 border-violet-500/40 text-violet-300",
  cyan: "from-cyan-500/20 to-cyan-600/10 border-cyan-500/40 text-cyan-300",
  pink: "from-pink-500/20 to-pink-600/10 border-pink-500/40 text-pink-300",
  emerald: "from-emerald-500/20 to-emerald-600/10 border-emerald-500/40 text-emerald-300",
  amber: "from-amber-500/20 to-amber-600/10 border-amber-500/40 text-amber-300",
};

function FlowNode({ step, index }: { step: FlowStep; index: number }) {
  const tone = TONE[step.tone ?? "cyan"];
  return (
    <div
      className="reveal flex flex-col items-center min-w-[120px] max-w-[140px]"
      style={{ transitionDelay: `${index * 80}ms` }}
    >
      <div
        className={`w-full rounded-2xl border bg-gradient-to-br px-3 py-3 text-center shadow-canva ${tone}`}
      >
        <div className="text-xs font-bold leading-tight">{step.label}</div>
        {step.sub && (
          <div className="mt-1 text-[10px] opacity-75 leading-snug">{step.sub}</div>
        )}
      </div>
    </div>
  );
}

function HorizontalFlow({ steps }: { steps: FlowStep[] }) {
  return (
    <div className="overflow-x-auto pb-2 -mx-2 px-2">
      <div className="flex items-center gap-1 min-w-max py-4">
        {steps.map((step, i) => (
          <div key={step.id} className="flex items-center">
            <FlowNode step={step} index={i} />
            {i < steps.length - 1 && (
              <div className="flex items-center px-1 shrink-0">
                <div className="w-6 sm:w-10 h-px bg-gradient-to-r from-primary/60 to-accent/60 relative">
                  <ArrowRight className="absolute -right-2 -top-2 w-4 h-4 text-primary/70" />
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

/** SVG platform hub — divisions orbiting central ThreatLens core */
export function PlatformHubDiagram() {
  const divisions = [
    { label: "SOC", angle: 0, color: "#10b981" },
    { label: "CTI", angle: 45, color: "#06b6d4" },
    { label: "Red Team", angle: 90, color: "#f43f5e" },
    { label: "Blue Team", angle: 135, color: "#3b82f6" },
    { label: "DFIR", angle: 180, color: "#8b5cf6" },
    { label: "AppSec", angle: 225, color: "#f97316" },
    { label: "Cloud", angle: 270, color: "#0ea5e9" },
    { label: "GRC", angle: 315, color: "#94a3b8" },
  ];
  const cx = 200;
  const cy = 200;
  const r = 130;

  return (
    <div className="reveal relative mx-auto w-full max-w-md aspect-square">
      <svg viewBox="0 0 400 400" className="w-full h-full" aria-label="Platform hub diagram">
        <defs>
          <linearGradient id="hubGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#8b5cf6" />
            <stop offset="50%" stopColor="#ec4899" />
            <stop offset="100%" stopColor="#06b6d4" />
          </linearGradient>
        </defs>
        {divisions.map((d) => {
          const rad = (d.angle * Math.PI) / 180;
          const x = cx + r * Math.cos(rad);
          const y = cy + r * Math.sin(rad);
          return (
            <g key={d.label}>
              <line x1={cx} y1={cy} x2={x} y2={y} stroke="url(#hubGrad)" strokeWidth="1" strokeOpacity="0.35" strokeDasharray="4 4" />
              <circle cx={x} cy={y} r="28" fill={d.color} fillOpacity="0.15" stroke={d.color} strokeWidth="1.5" />
              <text x={x} y={y + 4} textAnchor="middle" fill={d.color} fontSize="10" fontWeight="600">
                {d.label}
              </text>
            </g>
          );
        })}
        <circle cx={cx} cy={cy} r="52" fill="url(#hubGrad)" fillOpacity="0.25" stroke="url(#hubGrad)" strokeWidth="2" />
        <text x={cx} y={cy - 6} textAnchor="middle" fill="#e2e8f0" fontSize="13" fontWeight="700">
          ThreatLens
        </text>
        <text x={cx} y={cy + 12} textAnchor="middle" fill="#94a3b8" fontSize="9">
          Platform Hub
        </text>
      </svg>
      <p className="text-center text-xs text-muted-foreground mt-2">
        13 divisions · one login · role-based workspaces
      </p>
    </div>
  );
}

export function FlowDiagramTabs() {
  const [tab, setTab] = useState<FlowTabId>("pipeline");
  const active = FLOW_TABS.find((t) => t.id === tab)!;

  return (
    <div className="reveal rounded-3xl border border-border bg-card/80 backdrop-blur p-6 md:p-8 shadow-canva">
      <div className="flex flex-wrap gap-2 mb-6">
        {FLOW_TABS.map((t) => (
          <button
            key={t.id}
            type="button"
            onClick={() => setTab(t.id)}
            className={`px-4 py-2 rounded-xl text-xs font-semibold transition ${
              tab === t.id
                ? "bg-gradient-violet-pink text-white shadow-canva"
                : "bg-muted/50 text-muted-foreground hover:text-foreground hover:bg-muted"
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>
      <HorizontalFlow steps={active.steps} />
      <details className="mt-6 group">
        <summary className="flex items-center gap-2 text-xs text-muted-foreground cursor-pointer list-none select-none">
          <ChevronDown className="w-4 h-4 transition group-open:rotate-180" />
          View as text flow
        </summary>
        <p className="mt-2 text-sm text-muted-foreground font-mono leading-relaxed">
          {active.steps.map((s) => s.label).join(" → ")}
        </p>
      </details>
    </div>
  );
}

/** Layered stack diagram for free-tier resilience */
export function ResilienceStackDiagram() {
  const layers = [
    { label: "Static frontend", sub: "GitHub Pages CDN", w: "100%", color: "bg-cyan-500/20 border-cyan-500/40" },
    { label: "Live feed reads", sub: "feed-api → Turso (no stale cache fallback)", w: "92%", color: "bg-violet-500/20 border-violet-500/40" },
    { label: "Auth", sub: "Clerk → JWT bridge → RLS", w: "84%", color: "bg-pink-500/20 border-pink-500/40" },
    { label: "Storage guard", sub: "450 MB cap · 15-day retention", w: "76%", color: "bg-emerald-500/20 border-emerald-500/40" },
    { label: "Ingest pipeline", sub: "pg_cron + queue-worker every 5 min", w: "68%", color: "bg-amber-500/20 border-amber-500/40" },
  ];

  return (
    <div className="reveal space-y-3 py-4">
      {layers.map((l, i) => (
        <div key={l.label} className="flex justify-center" style={{ transitionDelay: `${i * 100}ms` }}>
          <div
            className={`rounded-2xl border px-4 py-3 ${l.color}`}
            style={{ width: l.w }}
          >
            <div className="text-sm font-bold">{l.label}</div>
            <div className="text-[11px] text-muted-foreground mt-0.5">{l.sub}</div>
          </div>
        </div>
      ))}
    </div>
  );
}
