/** Production GitHub Pages URL — always used for post-login return (never stay on Clerk). */
export const THREATLENS_LIVE_URL = "https://test12378.github.io/Threatintel-app/";

/** Vite base path, e.g. /Threatintel-app/ */
export function appBasePath(): string {
  const base = import.meta.env.BASE_URL || "/";
  return base.startsWith("/") ? base : `/${base}`;
}

/** Absolute app home — https://host/Threatintel-app/ */
export function clerkAppHomeUrl(): string {
  const path = appBasePath().replace(/\/?$/, "/");
  if (typeof window !== "undefined") {
    const origin = window.location.origin;
    // GitHub Pages production — always return canonical live URL for auth redirects
    if (origin.includes("github.io") && path.includes("Threatintel-app")) {
      return THREATLENS_LIVE_URL;
    }
    return `${origin}${path}`.replace(/([^:]\/)\/+/g, "$1");
  }
  return THREATLENS_LIVE_URL;
}

/** Full hash-route URL for HashRouter (in-app navigation). */
export function clerkHashUrl(route: string): string {
  const home = clerkAppHomeUrl().replace(/\/?$/, "/");
  const segment = route.replace(/^\/+/, "").replace(/\/+$/, "");
  return segment ? `${home}#/${segment}` : `${home}#/`;
}

/**
 * Where Clerk MUST send the user after sign-in / sign-up.
 * No hash — OAuth and Account Portal strip # fragments; HashRouter defaults to "/".
 */
export function clerkPostAuthRedirectUrl(): string {
  const fromEnv = import.meta.env.VITE_CLERK_SIGN_IN_FORCE_REDIRECT_URL as string | undefined;
  if (fromEnv?.startsWith("http")) return fromEnv.replace(/\/?$/, "/");
  return clerkAppHomeUrl().replace(/\/?$/, "/");
}

export const clerkSignInUrl = () => clerkHashUrl("sign-in");
export const clerkSignUpUrl = () => clerkHashUrl("sign-up");
export const clerkSsoCallbackUrl = () => clerkHashUrl("sso-callback");
export const clerkDashboardUrl = () => clerkHashUrl("");

/** React Router hash paths (internal navigation only). */
export const CLERK_SIGN_IN_PATH = "/sign-in";
export const CLERK_SIGN_UP_PATH = "/sign-up";
export const CLERK_SSO_CALLBACK_PATH = "/sso-callback";

/** Decode frontend API host from pk_test_… publishable key. */
export function clerkFrontendApiHost(): string {
  const key = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY as string | undefined;
  if (!key?.startsWith("pk_")) return "cheerful-moray-93.clerk.accounts.dev";
  const b64 = key.replace(/^pk_(test|live)_/, "");
  const padded = b64 + "==".slice((b64.length + 2) % 4);
  try {
    const decoded = atob(padded).replace(/\$$/, "").trim();
    if (decoded.includes("clerk")) return decoded;
  } catch { /* fall through */ }
  return "cheerful-moray-93.clerk.accounts.dev";
}

/** Clerk Account Portal host (hosted login page — always shows email/password UI). */
export function clerkAccountsHost(): string {
  return clerkFrontendApiHost().replace(".clerk.accounts.dev", ".accounts.dev");
}

/** Account Portal sign-in link — always includes redirect_url back to ThreatLens. */
export function clerkHostedSignInUrl(): string {
  const redirect = encodeURIComponent(clerkPostAuthRedirectUrl());
  return `https://${clerkAccountsHost()}/sign-in?redirect_url=${redirect}`;
}

export function clerkHostedSignUpUrl(): string {
  const redirect = encodeURIComponent(clerkPostAuthRedirectUrl());
  return `https://${clerkAccountsHost()}/sign-up?redirect_url=${redirect}`;
}

export function redirectToClerkSignIn(): void {
  window.location.assign(clerkHostedSignInUrl());
}

export function redirectToClerkSignUp(): void {
  window.location.assign(clerkHostedSignUpUrl());
}
