export function hubModulesByZone(zone: HubZone): HubModule[] {
  return RED_TEAM_HUB_MODULES.filter((m) => m.zone === zone);
}

/** Post-pentest navigation helpers */
export function labUrlForTarget(hostname: string, tab?: "free" | "tools" | "sandbox" | "bounty"): string {
  const params = new URLSearchParams({ target: hostname });
  if (tab) params.set("tab", tab);
  return `/offensive/lab?${params.toString()}`;
}

export function attackMatrixUrlForReport(findings: { mitreTechnique?: string }[]): string {
  const techniques = [...new Set(findings.map((f) => f.mitreTechnique).filter(Boolean))];
  if (!techniques.length) return "/offensive/attack-matrix";
  return `/offensive/attack-matrix?highlight=${encodeURIComponent(techniques.slice(0, 5).join(","))}`;
}

export function cyberSkillsUrlForFinding(keywords: string[]): string {
  const q = keywords.slice(0, 3).join(" ");
  return q ? `/offensive/cyber-skills?q=${encodeURIComponent(q)}` : "/offensive/cyber-skills";
}

export function engagementUrl(engagementId?: string | null): string {
  if (!engagementId) return "/offensive/engagements";
  return `/offensive/engagements?id=${encodeURIComponent(engagementId)}`;
}
