const AI_FUNCTIONS = new Set([
  "ai-brief", "ai-live-intel", "ai-fusion", "ai-security-agent",
  "ai-embedder", "ai-summarizer", "ai-entity-extractor", "ai-attck-mapper",
  "google-news-agent",
]);

async function countTable(
  table: string,
  filter?: (q: ReturnType<typeof supabase.from>) => ReturnType<typeof supabase.from>,
): Promise<number> {
  try {
    let q = supabase.from(table).select("id", { count: "exact", head: true });
    if (filter) q = filter(q) as typeof q;
    const { count, error } = await q;
    if (error) return 0;
    return count ?? 0;
  } catch {
    return 0;
  }
}

export async function fetchCompanyLiveStats(): Promise<CompanyLiveStats> {
  const since24h = new Date(Date.now() - 86_400_000).toISOString();

  const [
    threatItems,
    criticalThreats,
    highThreats,
    last24hThreats,
    activeSources,
    errorSources,
    openCases,
    authorizedUsers,
    aiSummarizedItems,
    queuedIngest,
    clients,
    latestItem,
    metrics,
  ] = await Promise.all([
    countTable("threat_items"),
    countTable("threat_items", (q) => q.eq("severity", "critical")),
    countTable("threat_items", (q) => q.eq("severity", "high")),
    countTable("threat_items", (q) => q.gte("fetched_at", since24h)),
    countTable("threat_sources", (q) => q.eq("enabled", true)),
    countTable("threat_sources", (q) => q.eq("enabled", true).like("last_status", "err:%")),
    countTable("cases", (q) => q.eq("status", "open")),
    countTable("authorized_users", (q) => q.eq("active", true)),
    countTable("threat_items", (q) => q.not("ai_summary", "is", null)),
    countTable("ingest_queue", (q) => q.eq("status", "queued")),
    countTable("clients"),
    supabase.from("threat_items").select("fetched_at").order("fetched_at", { ascending: false }).limit(1).maybeSingle(),
    supabase.from("function_metrics").select("function_name, success").order("ts", { ascending: false }).limit(300),
  ]);

  const metricRows = metrics.data ?? [];
  const fnSet = new Set(metricRows.map((m) => m.function_name));
  const ok = metricRows.filter((m) => m.success).length;
  const pipelineSuccessRate = metricRows.length > 0 ? Math.round((ok / metricRows.length) * 100) : null;

  return {
    threatItems,
    criticalThreats,
    highThreats,
    last24hThreats,
    activeSources,
    errorSources,
    openCases,
    authorizedUsers,
    aiSummarizedItems,
    queuedIngest,
    clients,
    lastIngestAt: latestItem.data?.fetched_at ?? null,
    pipelineFunctions: fnSet.size,
    pipelineSuccessRate,
  };
}

export async function fetchAIPipelineRows(): Promise<AIPipelineRow[]> {
  const { data } = await supabase
    .from("function_metrics")
    .select("function_name, duration_ms, items_processed, success, ts")
    .order("ts", { ascending: false })
    .limit(500);

  const rows = data ?? [];
  const byFn = new Map<string, { total: number; ok: number; avgMs: number; items: number; recent: string }>();

  for (const m of rows) {
    const name = m.function_name as string;
    if (!AI_FUNCTIONS.has(name) && !name.startsWith("ai-")) continue;
    const e = byFn.get(name) ?? { total: 0, ok: 0, avgMs: 0, items: 0, recent: m.ts as string };
    e.total++;
    if (m.success) e.ok++;
    e.avgMs = Math.round((e.avgMs * (e.total - 1) + (m.duration_ms ?? 0)) / e.total);
    e.items += (m.items_processed as number) ?? 0;
    if ((m.ts as string) > e.recent) e.recent = m.ts as string;
    byFn.set(name, e);
  }

  return [...byFn.entries()]
    .map(([functionName, s]) => ({
      functionName,
      calls: s.total,
      successPct: s.total ? Math.round((s.ok / s.total) * 100) : 0,
      avgMs: s.avgMs,
      itemsProcessed: s.items,
      lastRun: s.recent,
    }))
    .sort((a, b) => b.calls - a.calls);
}

