export async function checkPlatformHealth(): Promise<"operational" | "degraded" | "unknown"> {
  try {
    const { error } = await supabase.from("threat_items").select("id").limit(1);
    if (error) return "degraded";
    const s = await fetchCompanyLiveStats();
    if (s.errorSources > 0 && s.errorSources >= s.activeSources / 2) return "degraded";
    return "operational";
  } catch {
    return "unknown";
  }
}
