import { useState } from "react";
import {
  Brain, Briefcase, Cloud, Code, Crosshair, Layers, Radar, Scale, Search, Shield, Target, Users,
  ChevronRight, CheckCircle2,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { divisionsForLanding, DIVISION_CATEGORY_LABELS, type CompanyDivision } from "@/lib/landing-content";

const ICONS: Record<string, LucideIcon> = {
  radar: Radar,
  shield: Shield,
  crosshair: Crosshair,
  layers: Layers,
  search: Search,
  brain: Brain,
  cloud: Cloud,
  target: Target,
  scale: Scale,
  briefcase: Briefcase,
  code: Code,
  users: Users,
};

function DivisionCard({ division, expanded, onToggle }: {
  division: CompanyDivision;
  expanded: boolean;
  onToggle: () => void;
}) {
  const Icon = ICONS[division.icon] ?? Shield;
  const liveCount = division.tools.filter((t) => t.live).length;

  return (
    <div
      className={`reveal rounded-3xl border border-border bg-card overflow-hidden transition hover:shadow-canva ${
        expanded ? "ring-1 ring-primary/30" : ""
      }`}
    >
      <button
        type="button"
        onClick={onToggle}
        className="w-full text-left p-5 md:p-6 flex gap-4 items-start"
      >
        <div className={`shrink-0 w-12 h-12 rounded-2xl bg-gradient-to-br ${division.gradient} grid place-items-center shadow-canva`}>
          <Icon className="w-6 h-6 text-white" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <h3 className="font-display text-lg font-bold tracking-tight">{division.title}</h3>
            <span className="text-[10px] font-semibold uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
              {division.status}
            </span>
            {division.adminOnly && (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-violet-500/15 text-violet-300 border border-violet-500/30">
                Admin
              </span>
            )}
          </div>
          <p className="text-xs text-primary/90 font-medium mt-0.5">{division.tagline}</p>
          <p className="text-sm text-muted-foreground mt-2 line-clamp-2">{division.description}</p>
          <p className="text-xs text-muted-foreground mt-2">{liveCount} live tools</p>
        </div>
        <ChevronRight className={`w-5 h-5 shrink-0 text-muted-foreground transition ${expanded ? "rotate-90" : ""}`} />
      </button>

      {expanded && (
        <div className="px-5 md:px-6 pb-5 md:pb-6 border-t border-border/60 pt-4">
          <p className="text-[10px] uppercase tracking-widest text-muted-foreground mb-3">
            {DIVISION_CATEGORY_LABELS[division.category]}
          </p>
          <div className="grid sm:grid-cols-2 gap-2">
            {division.tools.map((tool) => (
              <div
                key={tool.route}
                className="flex items-start gap-2 rounded-xl bg-background/60 border border-border/60 px-3 py-2.5"
              >
                <CheckCircle2 className={`w-4 h-4 shrink-0 mt-0.5 ${tool.live ? "text-emerald-400" : "text-muted-foreground"}`} />
                <div>
                  <div className="text-sm font-semibold">{tool.label}</div>
                  {tool.description && (
                    <div className="text-[11px] text-muted-foreground leading-snug">{tool.description}</div>
                  )}
                </div>
              </div>
            ))}
          </div>
          {division.frameworks && (
            <div className="mt-3 flex flex-wrap gap-1.5">
              {division.frameworks.map((f) => (
                <span key={f} className="text-[10px] px-2 py-0.5 rounded-md bg-muted text-muted-foreground">
                  {f}
                </span>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export function DivisionShowcase() {
  const divisions = divisionsForLanding();
  const [expandedId, setExpandedId] = useState<string | null>("threat-intel");

  return (
    <div className="grid md:grid-cols-2 gap-4">
      {divisions.map((d) => (
        <DivisionCard
          key={d.id}
          division={d}
          expanded={expandedId === d.id}
          onToggle={() => setExpandedId(expandedId === d.id ? null : d.id)}
        />
      ))}
    </div>
  );
}
