import { AlertTriangle, Shield, RefreshCw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { usePlatformHealth } from "@/hooks/usePlatformHealth";

/** Non-blocking banner — site keeps running even when backend is degraded. */
export function PlatformGuardianBanner() {
  const { health, loading, refresh, worst } = usePlatformHealth();

  if (loading || !health || worst === "ok" || worst === "unknown") return null;

  const critical = health.checks.filter((c) => c.status === "critical");
  const warns = health.checks.filter((c) => c.status === "warn");

  return (
    <div
      className={`flex flex-wrap items-center gap-3 px-4 py-2 text-xs border-b ${
        worst === "critical"
          ? "bg-red-500/10 border-red-500/20 text-red-300"
          : "bg-amber-500/10 border-amber-500/20 text-amber-300"
      }`}
      role="status"
    >
      {worst === "critical" ? (
        <AlertTriangle className="h-4 w-4 shrink-0" />
      ) : (
        <Shield className="h-4 w-4 shrink-0" />
      )}
      <span className="flex-1 min-w-[200px]">
        {health.siteWillRun ? (
          <>Live feed sync issue — pulling fresh data from cloud. Hard-refresh if items look stale.</>
        ) : (
          "Platform issue detected — retry or check Settings → Free Storage"
        )}
        {(critical.length > 0 || warns.length > 0) && (
          <span className="text-muted-foreground ml-1">
            ({[...critical, ...warns].map((c) => c.service).join(", ")})
          </span>
        )}
      </span>
      <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => refresh()}>
        <RefreshCw className="h-3 w-3 mr-1" /> Recheck
      </Button>
    </div>
  );
}
