import { SignIn, useAuth } from "@clerk/clerk-react";
import { Link, Navigate } from "react-router-dom";
import { Shield, ArrowLeft } from "lucide-react";
import { clerkPostAuthRedirectUrl } from "@/lib/clerk-urls";

/**
 * Embedded Clerk sign-in using routing="virtual" — works on GitHub Pages + HashRouter
 * (virtual routing keeps all auth state in-memory and never touches the URL, so it
 * doesn't need server-side routes or the hosted Account Portal redirect). Post-auth
 * redirect is handled by ClerkProvider's signInForceRedirectUrl in main.tsx.
 */
export default function SignInPage() {
  const { isSignedIn, isLoaded } = useAuth();

  if (!isLoaded) {
    return (
      <div className="dark min-h-screen bg-background flex flex-col items-center justify-center gap-4 px-4">
        <Shield className="w-12 h-12 text-cyan-400 animate-pulse" />
        <p className="text-sm text-muted-foreground">Loading…</p>
      </div>
    );
  }

  if (isSignedIn) return <Navigate to="/hub" replace />;

  // Land on the Platform Hub after login (full URL incl. hash — embedded flow keeps it).
  const HUB_URL = `${clerkPostAuthRedirectUrl()}#/hub`;

  return (
    <div className="dark min-h-screen bg-background text-foreground flex flex-col">
      <header className="border-b border-border/60 px-4 sm:px-6 h-14 flex items-center">
        <Link to="/" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition">
          <ArrowLeft className="w-4 h-4" />
          Back to home
        </Link>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center px-4 py-12">
        <div className="flex items-center gap-2 mb-6">
          <Shield className="w-7 h-7 text-cyan-400" />
          <span className="font-display text-xl font-bold">ThreatLens</span>
        </div>
        <SignIn
          routing="virtual"
          signUpUrl="/sign-up"
          forceRedirectUrl={HUB_URL}
          fallbackRedirectUrl={HUB_URL}
          appearance={{ elements: { rootBox: "mx-auto", card: "shadow-canva" } }}
        />
        <p className="mt-6 text-xs text-muted-foreground">
          No account? <Link to="/sign-up" className="text-cyan-400 underline">Create one</Link>
        </p>
      </main>
    </div>
  );
}
