/** Live metrics for Red Team Lab Hub — Supabase + local pentest vault. */
import { supabase } from "@/integrations/supabase/client";
import { loadPentestReports, pentestToEngagement } from "@/lib/free-storage/adapters/pentest";

export type RedTeamLiveStats = {
  engagements: number;
  openFindings: number;
  phishingCampaigns: number;
  mitreTechniquesUsed: number;
};

type FindingRow = {
  severity?: string;
  status?: string;
  mitreTechnique?: string;
  mitre_technique?: string;
  mitre?: string;
};

function ingestFindings(findings: FindingRow[], techniques: Set<string>): number {
  let open = 0;
  for (const f of findings) {
    const status = String(f.status ?? "").toLowerCase();
    if (status !== "fixed" && status !== "remediated") open++;
    const t = f.mitreTechnique ?? f.mitre_technique ?? f.mitre;
    if (t) techniques.add(String(t));
  }
  return open;
}

export async function fetchRedTeamLiveStats(): Promise<RedTeamLiveStats> {
  const [engRes, phishRes, localReports] = await Promise.all([
    supabase.from("redteam_engagements").select("findings, objectives"),
    supabase.from("phishing_campaigns").select("id", { count: "exact", head: true }),
    loadPentestReports().catch(() => []),
  ]);

  const techniques = new Set<string>();
  let openFindings = 0;
  let engagements = engRes.data?.length ?? 0;

  const supabaseScanIds = new Set<string>();
  for (const row of engRes.data ?? []) {
    const findings = Array.isArray(row.findings) ? (row.findings as FindingRow[]) : [];
    openFindings += ingestFindings(findings, techniques);
    const obj = String(row.objectives ?? "");
    const m = obj.match(/scanId=([^;\s]+)/);
    if (m) supabaseScanIds.add(m[1]);
  }

  for (const artifact of localReports) {
    if (supabaseScanIds.has(artifact.data.scanId)) continue;
    engagements++;
    const eng = pentestToEngagement(artifact.data, artifact.id);
    openFindings += ingestFindings(eng.findings, techniques);
  }

  return {
    engagements,
    openFindings,
    phishingCampaigns: phishRes.count ?? 0,
    mitreTechniquesUsed: techniques.size,
  };
}
