import { getRuntimeConfig } from "@/lib/runtime-config";
import {
  fetchEdgeWithFailover,
  getActiveSupabaseClient,
} from "@/integrations/supabase/client";
import { anonAuthHeaders } from "@/lib/auth-adapter";

export type FeedItem = {
  id: string;
  title: string;
  link: string;
  excerpt?: string | null;
  severity: string;
  published_at: string;
  fetched_at?: string | null;
  source_name?: string | null;
  source_url?: string | null;
  category?: string | null;
  iocs?: unknown;
  ai_summary?: string | null;
  ai_summary_model?: string | null;
  ai_summary_generated_at?: string | null;
  confidence_score?: number;
  severity_reasons?: string[] | unknown;
  mitre_techniques?: string[] | unknown;
  threat_actors?: string[] | unknown;
  malware_families?: string[] | unknown;
  cross_source_count?: number;
  source_credibility?: number;
  [key: string]: unknown;
};

export type FeedQuery = {
  limit?: number;
  offset?: number;
  severity?: string;
  source_name?: string;
  sort?: "fetched" | "published";
};

export type NormalizedThreatItem = {
  id: string;
  title: string;
  link: string;
  excerpt: string | null;
  severity: "critical" | "high" | "medium" | "low" | "info";
  published_at: string;
  fetched_at: string;
  source_name: string | null;
  source_url: string | null;
  category: string | null;
  iocs: { cves?: string[]; ipv4?: string[]; domains?: string[]; sha256?: string[]; urls?: string[] } | null;
  confidence_score: number;
  severity_reasons: string[];
  mitre_techniques: string[];
  threat_actors: string[];
  malware_families: string[];
  ai_summary: string | null;
  ai_model: string | null;
  ai_summary_at: string | null;
  cross_source_count: number;
  source_credibility: number;
};

let _backendCache: "turso" | "supabase" | null = null;
const FEED_LIST_CACHE_MS = 8_000;
const feedListCache = new Map<string, { at: number; payload: { items: FeedItem[]; total: number; backend: "turso" | "supabase" } }>();

function envPrefersTurso(): boolean {
  const cfg = getRuntimeConfig();
  if (cfg.feedBackend === "supabase") return false;
  if (cfg.feedBackend === "turso") return true;
  // Default: prefer Turso via feed-api when not explicitly forced to supabase
  return true;
}

export function useTursoFeeds(): boolean {
  return envPrefersTurso();
}

export async function getFeedBackend(): Promise<"turso" | "supabase"> {
  return resolveFeedBackend();
}

async function resolveFeedBackend(): Promise<"turso" | "supabase"> {
  if (_backendCache) return _backendCache;
  if (!envPrefersTurso()) {
    _backendCache = "supabase";
    return "supabase";
  }
  try {
    const { response } = await fetchEdgeWithFailover("feed-api/stats", {
      headers: readHeaders(),
    });
    if (response.ok) {
      const json = await response.json();
      if (json?.turso_enabled || Number(json?.item_count ?? 0) > 0 || json?.backend === "turso") {
        _backendCache = "turso";
        return "turso";
      }
    }
  } catch {
    /* fall through */
  }
  _backendCache = "supabase";
  return "supabase";
}

export function normalizeFeedItem(row: FeedItem): NormalizedThreatItem {
  const published = row.published_at || new Date().toISOString();
  return {
    id: String(row.id),
    title: row.title,
    link: row.link,
    excerpt: row.excerpt ?? null,
    severity: (row.severity as NormalizedThreatItem["severity"]) || "info",
    published_at: published,
    fetched_at: (row.fetched_at as string) || published,
    source_name: row.source_name ?? null,
    source_url: (row.source_url as string) ?? null,
    category: row.category ?? null,
    iocs: (row.iocs as NormalizedThreatItem["iocs"]) ?? null,
    confidence_score: Number(row.confidence_score ?? 50),
    severity_reasons: Array.isArray(row.severity_reasons) ? row.severity_reasons as string[] : [],
    mitre_techniques: Array.isArray(row.mitre_techniques) ? row.mitre_techniques as string[] : [],
    threat_actors: Array.isArray(row.threat_actors) ? row.threat_actors as string[] : [],
    malware_families: Array.isArray(row.malware_families) ? row.malware_families as string[] : [],
    ai_summary: row.ai_summary ?? null,
    ai_model: (row.ai_summary_model as string) ?? null,
    ai_summary_at: (row.ai_summary_generated_at as string) ?? null,
    cross_source_count: Number(row.cross_source_count ?? 0),
    source_credibility: Number(row.source_credibility ?? 0),
  };
}

function readHeaders(): Record<string, string> {
  return anonAuthHeaders();
}

function cacheKey(opts: FeedQuery): string {
  return JSON.stringify({
    limit: opts.limit ?? 50,
    offset: opts.offset ?? 0,
    severity: opts.severity ?? "",
    source_name: opts.source_name ?? "",
    sort: opts.sort ?? "fetched",
  });
}

/** Fetch feeds — Turso via feed-api when configured, else Supabase. */
export async function fetchThreatFeeds(opts: FeedQuery = {}): Promise<{
  items: FeedItem[];
  total: number;
  backend: "turso" | "supabase";
}> {
  const limit = opts.limit ?? 50;
  const offset = opts.offset ?? 0;
  const key = cacheKey({ ...opts, limit, offset });
  const hit = feedListCache.get(key);
  if (hit && Date.now() - hit.at < FEED_LIST_CACHE_MS) {
    return hit.payload;
  }

  const backend = await resolveFeedBackend();

  if (backend === "turso") {
    const params = new URLSearchParams({
      limit: String(limit),
      offset: String(offset),
      sort: opts.sort ?? "fetched",
    });
    if (opts.severity) params.set("severity", opts.severity);
    if (opts.source_name) params.set("source_name", opts.source_name);

    try {
      const { response: res } = await fetchEdgeWithFailover(`feed-api?${params}`, {
        headers: readHeaders(),
      });
      if (res.ok) {
        const payload = await res.json();
        const result = {
          items: (payload.items ?? []) as FeedItem[],
          total: Number(payload.total ?? 0),
          backend: "turso" as const,
        };
        feedListCache.set(key, { at: Date.now(), payload: result });
        return result;
      }
    } catch { /* continue to error */ }
    throw new Error("Live feed-api unavailable — retry in a moment");
  }

  const db = await getActiveSupabaseClient();
  let q = db
    .from("threat_items")
    .select("*", { count: "exact" })
    .order("fetched_at", { ascending: false, nullsFirst: false })
    .range(offset, offset + limit - 1);

  if (opts.severity) q = q.eq("severity", opts.severity);
  if (opts.source_name) q = q.eq("source_name", opts.source_name);

  const { data, count, error } = await q;
  if (error) throw new Error(error.message);

  const result = {
    items: (data ?? []) as FeedItem[],
    total: count ?? 0,
    backend: "supabase" as const,
  };
  feedListCache.set(key, { at: Date.now(), payload: result });
  return result;
}

/** Single or paginated fetch — avoids N round-trips when limit ≤ 500. */
export async function fetchThreatFeedsBulk(opts: FeedQuery & { maxItems?: number } = {}): Promise<{
  items: NormalizedThreatItem[];
  total: number;
  backend: "turso" | "supabase";
}> {
  const maxItems = Math.min(opts.maxItems ?? 200, 500);
  const offset = opts.offset ?? 0;

  if (maxItems <= 500) {
    const batch = await fetchThreatFeeds({
      limit: maxItems,
      offset,
      severity: opts.severity,
      source_name: opts.source_name,
      sort: opts.sort ?? "fetched",
    });
    return {
      items: batch.items.map(normalizeFeedItem),
      total: batch.total,
      backend: batch.backend,
    };
  }

  const pageSize = 200;
  const all: FeedItem[] = [];
  let total = 0;
  let backend: "turso" | "supabase" = "supabase";
  let pageOffset = offset;

  while (all.length < maxItems) {
    const batch = await fetchThreatFeeds({
      limit: Math.min(pageSize, maxItems - all.length),
      offset: pageOffset,
      severity: opts.severity,
      source_name: opts.source_name,
      sort: opts.sort ?? "fetched",
    });
    backend = batch.backend;
    total = batch.total;
    all.push(...batch.items);
    if (batch.items.length < Math.min(pageSize, maxItems - all.length) || all.length >= total) break;
    pageOffset += batch.items.length;
  }

  return { items: all.map(normalizeFeedItem), total, backend };
}

export function clearFeedListCache(): void {
  feedListCache.clear();
}

/** Trigger cloud ingest queue (dispatcher + worker batches). Tries primary then secondary. */
export async function triggerFeedIngest(): Promise<{ ok: boolean; detail?: string }> {
  const headers = { ...readHeaders(), "Content-Type": "application/json" };
  try {
    const { response: dispatch } = await fetchEdgeWithFailover("queue-dispatcher", {
      method: "POST",
      headers,
      body: JSON.stringify({ max_jobs: 80 }),
    });
    if (dispatch.ok) {
      for (let i = 0; i < 2; i++) {
        await fetchEdgeWithFailover("queue-worker", {
          method: "POST",
          headers,
          body: JSON.stringify({ limit: 15 }),
        });
      }
    } else {
      await fetchEdgeWithFailover("fetch-feeds", {
        method: "POST",
        headers,
        body: JSON.stringify({
          names: ["BleepingComputer", "The Hacker News", "Dark Reading", "SecurityWeek", "Snyk Security"],
        }),
      });
    }
    clearFeedListCache();
    return { ok: true };
  } catch (e) {
    return { ok: false, detail: e instanceof Error ? e.message : "ingest failed" };
  }
}

export async function getFeedBackendStats(): Promise<{
  backend: string;
  turso_enabled: boolean;
  item_count: number;
  critical_count?: number;
  high_count?: number;
  project?: string;
} | null> {
  try {
    const { response, project } = await fetchEdgeWithFailover("feed-api/stats", {
      headers: readHeaders(),
    });
    if (!response.ok) return null;
    const json = await response.json();
    return { ...json, project: project.id };
  } catch {
    return null;
  }
}
