import { SignUp, useAuth } from "@clerk/clerk-react";
import { Link, Navigate } from "react-router-dom";
import { Shield, ArrowLeft } from "lucide-react";
import { clerkPostAuthRedirectUrl } from "@/lib/clerk-urls";

/** Embedded Clerk sign-up (routing="virtual") — GitHub Pages + HashRouter safe. */
export default function SignUpPage() {
  const { isSignedIn, isLoaded } = useAuth();

  if (!isLoaded) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Shield className="w-10 h-10 text-cyan-400 animate-pulse" />
      </div>
    );
  }
  if (isSignedIn) return <Navigate to="/" replace />;

  return (
    <div className="dark min-h-screen bg-background text-foreground flex flex-col">
      <header className="border-b border-border/60 px-4 sm:px-6 h-14 flex items-center">
        <Link to="/" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition">
          <ArrowLeft className="w-4 h-4" /> Back to home
        </Link>
      </header>
      <main className="flex-1 flex flex-col items-center justify-center px-4 py-12">
        <div className="flex items-center gap-2 mb-6">
          <Shield className="w-7 h-7 text-cyan-400" />
          <span className="font-display text-xl font-bold">ThreatLens</span>
        </div>
        <SignUp
          routing="virtual"
          signInUrl="/sign-in"
          forceRedirectUrl={clerkPostAuthRedirectUrl()}
          fallbackRedirectUrl={clerkPostAuthRedirectUrl()}
          appearance={{ elements: { rootBox: "mx-auto", card: "shadow-canva" } }}
        />
      </main>
    </div>
  );
}
