import { useEffect, useState } from "react";
import { getRuntimeConfig } from "@/lib/runtime-config";
import { anonAuthHeaders } from "@/lib/auth-adapter";

export type LiveFeedStats = {
  itemCount: number | null;
  criticalCount: number | null;
  loading: boolean;
};

export function useLiveFeedStats(): LiveFeedStats {
  const [itemCount, setItemCount] = useState<number | null>(null);
  const [criticalCount, setCriticalCount] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const cfg = getRuntimeConfig();
    if (cfg.missingSupabaseConfig) {
      setLoading(false);
      return;
    }

    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(`${cfg.supabaseUrl}/functions/v1/feed-api/stats`, {
          headers: anonAuthHeaders(),
          cache: "no-store",
        });
        if (!res.ok || cancelled) return;
        const data = await res.json();
        if (cancelled) return;
        setItemCount(typeof data.item_count === "number" ? data.item_count : null);
        setCriticalCount(typeof data.critical_count === "number" ? data.critical_count : null);
      } catch {
        /* keep static fallbacks */
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, []);

  return { itemCount, criticalCount, loading };
}
