import { createContext, useContext } from "react";
import { useUser } from "@/lib/auth-adapter";
import { hasThreatIntelAccess, isPlatformAdmin } from "@/lib/admin-config";

export type UserRole = "admin" | "user" | null;

interface RoleCtx {
  role: UserRole;
  isAdmin: boolean;
  userEmail: string | null;
}

const RoleContext = createContext<RoleCtx>({ role: null, isAdmin: false, userEmail: null });

function computeRole(email: string | null | undefined, signedIn: boolean): UserRole {
  if (!signedIn) return null;
  if (!email) return "user";
  return hasThreatIntelAccess(email) ? "admin" : "user";
}

export function RoleProvider({ children }: { children: React.ReactNode }) {
  const { user, isSignedIn } = useUser();
  const userEmail = user?.primaryEmailAddress?.emailAddress ?? null;
  const role = computeRole(userEmail, !!isSignedIn);

  return (
    <RoleContext.Provider value={{ role, isAdmin: isPlatformAdmin(userEmail), userEmail }}>
      {children}
    </RoleContext.Provider>
  );
}

export const useRole = () => useContext(RoleContext);
