import { useQuery } from "@tanstack/react-query";
import { fetchAllRedTeamToolStatuses, type RedTeamToolStatus } from "@/lib/redteam/tools";
import { useRedTeamLabConfig } from "@/hooks/useRedTeamLabConfig";

export function useRedTeamToolStatuses() {
  const { data: labConfig } = useRedTeamLabConfig();

  return useQuery({
    queryKey: ["redteam", "tool-status", labConfig?.labHost, labConfig?.source],
    queryFn: () => fetchAllRedTeamToolStatuses(labConfig),
    staleTime: 30_000,
    refetchInterval: 60_000,
    enabled: labConfig !== undefined,
  });
}

export type { RedTeamToolStatus };
