import { createRoot } from "react-dom/client";
import * as Sentry from "@sentry/react";
import { ClerkProvider } from "@clerk/clerk-react";
import App from "./App.tsx";
import { ConfigErrorScreen } from "@/components/ConfigErrorScreen";
import { ClerkConfigScreen } from "@/components/ClerkConfigScreen";
import { ThemeProvider } from "@/components/theme-provider";
import { getRuntimeConfig } from "@/lib/runtime-config";
import { initializeCacheCleanup } from "@/lib/cache-cleanup";
import { clearChunkReloadFlag } from "@/lib/lazy-with-retry";
import { clerkPostAuthRedirectUrl, THREATLENS_LIVE_URL } from "@/lib/clerk-urls";
import "./index.css";

// ── Sentry — error monitoring + performance tracing ───────────────────────────
const SENTRY_DSN = import.meta.env.VITE_SENTRY_DSN as string | undefined;
if (SENTRY_DSN) {
  Sentry.init({
    dsn: SENTRY_DSN,
    integrations: [
      Sentry.browserTracingIntegration(),
      Sentry.replayIntegration({
        maskAllText:   true,   // GDPR: mask all text in session replays
        blockAllMedia: true,
      }),
    ],
    tracesSampleRate:        0.1,   // 10% of transactions — keeps quota low
    replaysSessionSampleRate: 0.05, // 5% of sessions
    replaysOnErrorSampleRate: 1.0,  // 100% of error sessions
    environment: import.meta.env.MODE,
    beforeSend(event) {
      // Strip auth tokens from request headers
      if (event.request?.headers) {
        delete event.request.headers["Authorization"];
        delete event.request.headers["apikey"];
      }
      // Strip tokens from URL params
      if (event.request?.url) {
        event.request.url = event.request.url.replace(/[?&](key|token|apikey)=[^&]*/gi, "");
      }
      return event;
    },
  });
}

// Initialize cache cleanup on app load + clear stale chunk-reload flag
initializeCacheCleanup();
clearChunkReloadFlag();

// Never cache JS bundles — unregister any stale service workers on every load
if ("serviceWorker" in navigator) {
  navigator.serviceWorker.getRegistrations().then((regs) =>
    Promise.all(regs.map((r) => r.unregister())),
  );
}
if ("caches" in window) {
  caches.keys().then((keys) => Promise.all(keys.map((k) => caches.delete(k))));
}

const runtimeConfig = getRuntimeConfig();

const CLERK_KEY = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY as string | undefined;
const clerkConfigured = !!CLERK_KEY?.startsWith("pk_");
if (!clerkConfigured && import.meta.env.DEV) {
  console.warn("Missing VITE_CLERK_PUBLISHABLE_KEY — Clerk login will not work until set.");
}

/** Always return to ThreatLens after auth — never Clerk's /default-redirect page. */
const AUTH_RETURN_URL = clerkPostAuthRedirectUrl();

function RootShell() {
  if (runtimeConfig.missingSupabaseConfig) return <ConfigErrorScreen />;
  if (!clerkConfigured) return <ClerkConfigScreen />;
  return <App />;
}

createRoot(document.getElementById("root")!).render(
  <ThemeProvider attribute="class" defaultTheme="dark" enableSystem={false}>
    {clerkConfigured ? (
      <ClerkProvider
        publishableKey={CLERK_KEY!}
        signInForceRedirectUrl={AUTH_RETURN_URL}
        signUpForceRedirectUrl={AUTH_RETURN_URL}
        signInFallbackRedirectUrl={AUTH_RETURN_URL}
        signUpFallbackRedirectUrl={AUTH_RETURN_URL}
        afterSignOutUrl={AUTH_RETURN_URL}
        allowedRedirectOrigins={[
          THREATLENS_LIVE_URL.replace(/\/$/, ""),
          "https://test12378.github.io",
          typeof window !== "undefined" ? window.location.origin : "https://test12378.github.io",
        ]}
      >
        <RootShell />
      </ClerkProvider>
    ) : (
      <RootShell />
    )}
  </ThemeProvider>,
);
