import { Suspense } from "react";
import { Routes, Route } from "react-router-dom";
import { SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { ThemeToggle } from "@/components/ThemeToggle";
import { ErrorBoundary } from "@/components/ErrorBoundary";
import { PlatformGuardianBanner } from "@/components/platform/PlatformGuardianBanner";
import { WorkspaceSidebar } from "@/components/workspace/WorkspaceSidebar";
import WorkspaceDashboard from "@/pages/workspace/WorkspaceDashboard";
import RedTeamDashboard from "@/pages/redteam/RedTeamDashboard";
import { renderWorkspacePage } from "@/config/workspace-pages";
import type { WorkspaceConfig } from "@/config/workspaces";
import NotFound from "@/pages/NotFound";

type Props = {
  config: WorkspaceConfig;
  routeSkeleton: React.ReactNode;
  statusIndicator?: React.ReactNode;
};

export function WorkspaceShell({ config, routeSkeleton, statusIndicator }: Props) {
  const { theme } = config;

  return (
    <SidebarProvider>
      <div className="flex min-h-screen w-full bg-background">
        <WorkspaceSidebar config={config} />
        <div className="flex flex-1 flex-col">
          <header
            className="sticky top-0 z-40 flex h-14 items-center gap-3 px-4 header-glass"
            style={{ borderBottom: `1px solid rgba(${theme.accentRgb},0.12)` }}
          >
            <SidebarTrigger
              className="text-slate-400 transition-colors"
              style={{ ["--hover" as string]: theme.accentLight }}
            />
            <div className="flex items-center gap-2.5">
              <span className="relative flex h-2 w-2 shrink-0">
                <span
                  className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-50"
                  style={{ background: theme.accent }}
                />
                <span className="relative inline-flex rounded-full h-2 w-2" style={{ background: theme.accent }} />
              </span>
              <span
                className="hidden sm:block text-xs font-semibold uppercase tracking-widest"
                style={{
                  background: `linear-gradient(90deg, ${theme.gradientFrom}, ${theme.gradientTo})`,
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                }}
              >
                {theme.headerLabel}
              </span>
            </div>
            <div className="ml-auto flex items-center gap-2">
              {statusIndicator}
              <span
                className="hidden md:flex items-center gap-1.5 text-[11px] text-slate-500 px-2.5 py-1 rounded-full"
                style={{
                  background: `rgba(${theme.accentRgb},0.08)`,
                  border: `1px solid rgba(${theme.accentRgb},0.15)`,
                }}
              >
                <span className="h-1.5 w-1.5 rounded-full animate-pulse" style={{ background: theme.accent }} />
                {theme.statusLabel}
              </span>
              <ThemeToggle />
            </div>
          </header>
          <PlatformGuardianBanner />
          <main className="flex-1 overflow-auto">
            <ErrorBoundary>
              <Suspense fallback={routeSkeleton}>
                <Routes>
                  <Route
                    index
                    element={
                      config.divisionId === "red-team" ? (
                        <RedTeamDashboard />
                      ) : (
                        <WorkspaceDashboard config={config} />
                      )
                    }
                  />
                  {config.routes.map(({ segment, adminOnly }) => (
                    <Route
                      key={segment}
                      path={segment}
                      element={renderWorkspacePage(segment, adminOnly) ?? <NotFound />}
                    />
                  ))}
                  <Route path="*" element={<NotFound />} />
                </Routes>
              </Suspense>
            </ErrorBoundary>
          </main>
        </div>
      </div>
    </SidebarProvider>
  );
}
