// Supabase client — auth via Clerk JWT (template "supabase") through accessToken callback.
// Primary singleton stays for sync imports; use getActiveSupabaseClient() for failover-aware calls.
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";
import { getRuntimeConfig } from "@/lib/runtime-config";
import { getSupabaseAccessToken } from "@/lib/auth-adapter";

export {
  getActiveSupabaseClient,
  fetchEdgeWithFailover,
  resolveHealthyProject,
  invalidateSupabaseHealthCache,
} from "@/lib/supabase-failover";

const runtimeConfig = getRuntimeConfig();

/** Primary project client (default). Prefer getActiveSupabaseClient() when failover matters. */
export const supabase = createClient<Database>(
  runtimeConfig.supabaseUrl,
  runtimeConfig.supabasePublishableKey,
  {
    accessToken: async () => getSupabaseAccessToken(),
  },
);
