import { useQuery } from "@tanstack/react-query";
import { fetchRedTeamLiveStats } from "@/lib/redteam/live-data";

export function useRedTeamLiveStats() {
  return useQuery({
    queryKey: ["redteam", "live-stats"],
    queryFn: fetchRedTeamLiveStats,
    staleTime: 30_000,
    refetchInterval: 60_000,
  });
}
