// ── Auto-heal status indicator ────────────────────────────────────────────────
function AutoHealIndicator() {
  const [healthy, setHealthy] = useState<boolean | null>(null);

  useEffect(() => {
    const check = async () => {
      try {
        const { error } = await supabase.from("threat_items").select("id").limit(1);
        setHealthy(!error);
      } catch { setHealthy(false); }
    };
    check();
    const t = setInterval(check, 60_000);
    return () => clearInterval(t);
  }, []);

  if (healthy === null) return null;
  return (
    <span
      title={healthy ? "All systems operational" : "Data source issue detected — auto-heal active"}
      className="hidden sm:flex items-center gap-1 text-[10px] text-muted-foreground"
    >
      {healthy ? (
        <ShieldCheck className="h-3.5 w-3.5 text-green-500" />
      ) : (
        <AlertCircle className="h-3.5 w-3.5 text-orange-400 animate-pulse" />
      )}
      {healthy ? "Operational" : "Auto-healing…"}
    </span>
  );
}

// ── Live Notification Bell ─────────────────────────────────────────────────────
type NotifItem = { id: string; title: string; severity: string; category?: string; source_name: string; published_at: string; link?: string };

const NOTIF_EXCLUDED = '("OpenPhish","OpenPhish Feed","PhishTank Stats","PhishTank","Vulners News","VulDB","VulDB Recent","MalwareBazaar Recent","MalwareBazaar")';
const isNotifExcluded = (s: string) => ["openphish","phishtank","vulners","vuldb","malwarebazaar"].some(p => (s || "").toLowerCase().includes(p));

const MALWARE_NOTIF_KW = ["malware","trojan","stealer","backdoor","botnet","infostealer","rootkit","ransomware","cobalt strike"];
const isMalwareThreat = (item: NotifItem) =>
  item.category === "malware" ||
  MALWARE_NOTIF_KW.some(k => `${item.title} `.toLowerCase().includes(k));

const ALERT_RECIPIENT = "ghostserver32789@gmail.com";

function NotificationBell() {
  const navigate = useNavigate();
  const [items, setItems] = useState<NotifItem[]>([]);
  const [unread, setUnread] = useState(0);
  const [open, setOpen] = useState(false);
  // Track alerted IDs so we never double-email on reconnect
  const alertedIds = useRef<Set<string>>(new Set());

  // Fire n8n webhook → email when a NEW critical/high item arrives via Realtime
  const fireEmailAlert = async (item: NotifItem) => {
    if (alertedIds.current.has(item.id)) return;
    alertedIds.current.add(item.id);
    try {
      await fetch("/api/n8n/webhook/threatlens-critical-alert", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          source: "ThreatLens Realtime",
          timestamp: new Date().toISOString(),
          title: item.title,
          severity: item.severity,
          category: item.category || "threat-intel",
          type: item.severity === "critical" || item.severity === "high"
            ? `${item.severity.toUpperCase()} Threat Alert`
            : isMalwareThreat(item)
            ? "Trending Malware Threat"
            : "Threat Intelligence Alert",
          description: `New ${item.severity.toUpperCase()} threat detected from ${item.source_name}`,
          recipients: ALERT_RECIPIENT,
          link: item.link || "",
          source_name: item.source_name,
          iocs: "",
        }),
        signal: AbortSignal.timeout(8000),
      });
    } catch { /* n8n offline — Supabase edge fn handles email instead */ }
  };

  useEffect(() => {
    const loadAlerts = async () => {
      const since = new Date(Date.now() - 4 * 60 * 60 * 1000).toISOString();
      const { data } = await supabase
        .from("threat_items")
        .select("id,title,severity,category,source_name,published_at,link")
        .not("source_name", "in", NOTIF_EXCLUDED)
        .or("severity.in.(critical,high),category.eq.malware")
        .gte("published_at", since)
        .order("published_at", { ascending: false })
        .limit(30);
      const filtered = (data || []).filter(i =>
        i.severity === "critical" || i.severity === "high" || isMalwareThreat(i as NotifItem)
      ) as NotifItem[];
      setItems(filtered);
      setUnread(filtered.length);
    };
    loadAlerts();
    const sub = supabase
      .channel("notif_bell")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "threat_items" }, (payload) => {
        const item = payload.new as NotifItem;
        if (isNotifExcluded(item.source_name)) return;
        const isRelevant = item.severity === "critical" || item.severity === "high" || isMalwareThreat(item);
        if (isRelevant) {
          setItems(prev => [item, ...prev].slice(0, 30));
          if (!open) setUnread(n => n + 1);
          // Email for critical, high, AND malware threats — all from approved sources
          fireEmailAlert(item);
        }
      })
      .subscribe();
    return () => { supabase.removeChannel(sub); };
  }, [open]);

  const sevColor: Record<string, string> = {
    critical: "bg-red-500/15 text-red-400 border-red-500/30",
    high: "bg-orange-500/15 text-orange-400 border-orange-500/30",
    medium: "bg-yellow-500/15 text-yellow-400 border-yellow-500/30",
    low: "bg-green-500/15 text-green-400 border-green-500/30",
  };

  const timeAgo = (iso: string) => {
    const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
    if (m < 1) return "just now";
    if (m < 60) return `${m}m ago`;
    return `${Math.floor(m / 60)}h ago`;
  };

  return (
    <Popover open={open} onOpenChange={(v) => { setOpen(v); if (v) setUnread(0); }}>
      <PopoverTrigger asChild>
        <Button size="sm" variant="ghost" className="relative h-8 w-8 p-0">
          <Bell className="h-4 w-4" />
          {unread > 0 && (
            <span className="absolute -top-0.5 -right-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-destructive text-[9px] font-bold text-white">
              {unread > 9 ? "9+" : unread}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-96 p-0">
        <div className="flex items-center justify-between px-4 py-3 border-b border-border/60">
          <div className="flex items-center gap-2">
            <Bell className="h-4 w-4 text-primary" />
            <span className="text-sm font-semibold">Recent Alerts</span>
            <span className="text-xs text-muted-foreground">(last 4h · critical · high · malware)</span>
          </div>
        </div>
        <ScrollArea className="max-h-[400px]">
          {items.length === 0 ? (
            <div className="px-4 py-8 text-center text-sm text-muted-foreground">
              No critical, high or malware threats in the last 4 hours.
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {items.map(item => (
                <div key={item.id} className="px-4 py-3 hover:bg-muted/40 transition-colors">
                  <div className="flex items-start gap-2">
                    <div className="flex flex-col gap-1 shrink-0 mt-0.5">
                      <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded border ${sevColor[item.severity] ?? sevColor.high}`}>
                        {item.severity.toUpperCase()}
                      </span>
                      {isMalwareThreat(item) && (
                        <span className="text-[9px] font-bold px-1.5 py-0.5 rounded border bg-orange-500/15 text-orange-400 border-orange-500/30">
                          MALWARE
                        </span>
                      )}
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="text-xs font-medium leading-snug line-clamp-2">{item.title}</p>
                      <div className="mt-1 flex items-center gap-2 text-[10px] text-muted-foreground">
                        <span>{item.source_name}</span>
                        <span>·</span>
                        <span>{timeAgo(item.published_at)}</span>
                        {item.link && (
                          <a href={item.link} target="_blank" rel="noreferrer" className="ml-auto text-primary hover:underline flex items-center gap-0.5">
                            <ExternalLink className="h-2.5 w-2.5" /> View
                          </a>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </ScrollArea>
        <div className="border-t border-border/60 px-4 py-2 text-[10px] text-muted-foreground text-center">
          Live via Supabase Realtime · <span className="text-primary cursor-pointer hover:underline" onClick={() => { setOpen(false); navigate("/ops/soc"); }}>Go to SOC Dashboard →</span>
        </div>
      </PopoverContent>
    </Popover>
  );
}

