const CLERK_RETURN_RE = /(?:^|[?&])__clerk_(?:status|ticket|db_jwt|handshake|synced)=/;

/** Strip Clerk handshake query params after session is established (keeps hash routes clean). */
function ClerkReturnCleanup() {
  const { isLoaded } = useAuth();
  useEffect(() => {
    if (!isLoaded || typeof window === "undefined") return;
    if (!CLERK_RETURN_RE.test(window.location.search)) return;
    const url = new URL(window.location.href);
    for (const key of [...url.searchParams.keys()]) {
      if (key.startsWith("__clerk_")) url.searchParams.delete(key);
    }
    const next = url.pathname + (url.search || "") + url.hash;
    window.history.replaceState(null, "", next || url.pathname);
  }, [isLoaded]);
  return null;
}

function RootRouter() {
  const { isLoaded, isSignedIn: signedIn } = useUser();

  if (!isLoaded) return <RoleLoadingScreen />;
  if (!signedIn) return <PublicShell />;
  return <RoleRouter />;
}

const App = () => (
  <Sentry.ErrorBoundary
    fallback={({ error, resetError }) => (
      <div className="min-h-screen flex items-center justify-center p-8 text-center">
        <div className="max-w-md space-y-4">
          <h2 className="text-xl font-bold text-destructive">Something went wrong</h2>
          <p className="text-sm text-muted-foreground">
            {(error instanceof Error ? error.message : String(error)).slice(0, 300) || "Unknown error"}
          </p>
          <button onClick={resetError} className="text-primary underline text-sm">Try again</button>
        </div>
      </div>
    )}
  >
    <QueryClientProvider client={queryClient}>
      <BackgroundDataSync />
      <TooltipProvider>
        <Toaster />
        <Sonner />
        <SecurityProvider>
          <RoleProvider>
            <HashRouter>
              <ClerkReturnCleanup />
              <RootRouter />
            </HashRouter>
          </RoleProvider>
        </SecurityProvider>
      </TooltipProvider>
    </QueryClientProvider>
  </Sentry.ErrorBoundary>
);

export default App;
