import { useNavigate, Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ArrowRight, Loader2, Sparkles, Shield } from "lucide-react";
import type { WorkspaceConfig } from "@/config/workspaces";
import { useDivisionMetrics, usePlatformHealth } from "@/hooks/useCompanyLiveData";

type Props = { config: WorkspaceConfig };

export default function WorkspaceDashboard({ config }: Props) {
  const navigate = useNavigate();
  const { data: health, isLoading: healthLoading } = usePlatformHealth();
  const { data: metrics, isLoading: metricsLoading } = useDivisionMetrics(config.divisionId);
  const Icon = config.icon;
  const { theme } = config;
  const liveTools = config.navGroups.find((g) => g.label === "Modules")?.items ?? [];

  return (
    <div className="p-4 md:p-6 space-y-6 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <div
            className="inline-flex items-center gap-2 rounded-full px-3 py-1 text-xs mb-3 border"
            style={{
              borderColor: `rgba(${theme.accentRgb},0.25)`,
              background: `rgba(${theme.accentRgb},0.1)`,
              color: theme.accentLight,
            }}
          >
            <Sparkles className="h-3.5 w-3.5" />
            {config.title}
          </div>
          <h1 className="text-2xl md:text-3xl font-bold" style={{ color: theme.accentLight }}>
            {config.title}
          </h1>
          <p className="text-sm text-muted-foreground mt-1 max-w-xl">{config.tagline}</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" size="sm" asChild>
            <Link to="/hub">
              <Shield className="h-4 w-4 mr-1.5" />
              Platform Hub
            </Link>
          </Button>
          {config.root !== "/" && (
            <Button variant="outline" size="sm" asChild>
              <Link to="/">Threat Intel</Link>
            </Button>
          )}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3 rounded-xl border border-border/60 bg-card/40 px-4 py-3 text-xs">
        {healthLoading ? (
          <Loader2 className="h-3.5 w-3.5 animate-spin text-muted-foreground" />
        ) : (
          <span className="flex items-center gap-2">
            <span className="relative flex h-2 w-2">
              <span
                className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-50"
                style={{ background: theme.accent }}
              />
              <span className="relative inline-flex rounded-full h-2 w-2" style={{ background: theme.accent }} />
            </span>
            <span style={{ color: theme.accentLight }} className="font-semibold capitalize">
              {health ?? "checking"}
            </span>
          </span>
        )}
        <Badge variant="outline">{liveTools.length} modules</Badge>
        <span className="text-muted-foreground">{config.subtitle}</span>
      </div>

      {metricsLoading ? (
        <div className="text-xs text-muted-foreground flex items-center gap-2">
          <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading live KPIs…
        </div>
      ) : metrics && metrics.length > 0 ? (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 auto-rows-fr">
          {metrics.map((m) => (
            <Card key={m.label} className="border-border/50 bg-card/50">
              <CardContent className="pt-4 pb-3">
                <p className="text-2xl font-bold tabular-nums" style={{ color: theme.accentLight }}>
                  {m.value}
                </p>
                <p className="text-[10px] uppercase tracking-wider text-muted-foreground mt-1">{m.label}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : null}

      <div>
        <h2 className="text-sm font-semibold uppercase tracking-wider text-muted-foreground mb-3">
          Workspace modules
        </h2>
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 auto-rows-fr">
          {liveTools.map((item) => {
            const ModIcon = item.icon;
            return (
              <Card
                key={item.url}
                className="border-border/60 transition-colors cursor-pointer group h-full flex flex-col hover:shadow-lg"
                style={{ borderColor: undefined }}
                onClick={() => navigate(item.url)}
                onKeyDown={(e) => e.key === "Enter" && navigate(item.url)}
                role="button"
                tabIndex={0}
              >
                <CardHeader className="pb-2">
                  <div
                    className={`flex h-10 w-10 items-center justify-center rounded-lg mb-2 bg-gradient-to-br ${config.gradient}`}
                  >
                    <ModIcon className="h-5 w-5 text-white" />
                  </div>
                  <CardTitle className="text-base group-hover:opacity-90 transition-colors">
                    {item.title}
                  </CardTitle>
                  <CardDescription className="text-xs line-clamp-2">
                    Open module
                  </CardDescription>
                </CardHeader>
                <CardContent className="pt-0 mt-auto">
                  <span className="text-xs flex items-center gap-1" style={{ color: theme.accentLight }}>
                    Open <ArrowRight className="h-3 w-3 group-hover:translate-x-0.5 transition-transform" />
                  </span>
                </CardContent>
              </Card>
            );
          })}
        </div>
      </div>
    </div>
  );
}
