import { Link } from "react-router-dom";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Loader2, Server, Sparkles, Terminal } from "lucide-react";
import { useRedTeamLabConfig } from "@/hooks/useRedTeamLabConfig";
import { useRedTeamToolStatuses } from "@/hooks/useRedTeamTools";
import { RED_TEAM_TOOLS } from "@/lib/redteam/tools";

const MODE_STYLE: Record<string, string> = {
  hosted: "border-emerald-500/30 text-emerald-400 bg-emerald-500/10",
  free: "border-cyan-500/30 text-cyan-400 bg-cyan-500/10",
  local: "border-amber-500/30 text-amber-400 bg-amber-500/10",
};

export function LabStatusStrip() {
  const { data: lab, isLoading: labLoading } = useRedTeamLabConfig();
  const { data: toolStatuses, isLoading: toolsLoading } = useRedTeamToolStatuses();

  const mode = lab?.mode ?? "free";
  const onlineTools = toolStatuses
    ? Object.values(toolStatuses).filter((s) => s === "online").length
    : 0;
  const hostedReady = mode === "hosted" && !!(lab?.kaliUrl || lab?.labHost);

  return (
    <div className="rounded-xl border border-rose-500/20 bg-gradient-to-r from-rose-500/5 via-card/40 to-cyan-500/5 p-4 flex flex-wrap items-center gap-3">
      <div className="flex items-center gap-2 min-w-[140px]">
        <Terminal className="h-4 w-4 text-rose-400 shrink-0" />
        <span className="text-sm font-medium">Red Team Lab</span>
      </div>

      {labLoading || toolsLoading ? (
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
      ) : (
        <>
          <Badge variant="outline" className={MODE_STYLE[mode] ?? MODE_STYLE.free}>
            {mode === "hosted" ? "Hosted VMs" : mode === "local" ? "Local dev" : "Free tier ($0)"}
          </Badge>
          {hostedReady && (
            <Badge variant="outline" className="border-emerald-500/30 text-emerald-400 text-[10px]">
              <Server className="h-3 w-3 mr-1 inline" />
              Kali / target ready
            </Badge>
          )}
          <span className="text-xs text-muted-foreground">
            {onlineTools}/{RED_TEAM_TOOLS.length} tools online
          </span>
          {lab?.source && lab.source !== "none" && (
            <span className="text-[10px] text-muted-foreground hidden sm:inline">
              config: {lab.source}
            </span>
          )}
        </>
      )}

      <div className="flex flex-wrap gap-2 ml-auto">
        <Button size="sm" variant="outline" asChild>
          <Link to="/offensive/lab?tab=free">
            <Sparkles className="h-3.5 w-3.5 mr-1.5" />
            Free lab
          </Link>
        </Button>
        {hostedReady && (
          <Button size="sm" variant="outline" asChild>
            <Link to="/offensive/lab?tab=sandbox">Hosted VMs</Link>
          </Button>
        )}
        <Button size="sm" className="bg-rose-600 hover:bg-rose-500" asChild>
          <Link to="/offensive/pentest-agent">Run pentest</Link>
        </Button>
      </div>
    </div>
  );
}
