/**
 * Multi-project Supabase helpers — primary → secondary failover for reads / edge calls.
 * Does not sync data between projects; dual-write ingest separately (see scripts/run-feed-ingest.sh).
 */
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/integrations/supabase/types";
import { getRuntimeConfig, getSupabaseProjects, type SupabaseProjectConfig } from "@/lib/runtime-config";
import { getSupabaseAccessToken, anonAuthHeaders } from "@/lib/auth-adapter";

const HEALTH_TTL_MS = 45_000;
const HEALTH_TIMEOUT_MS = 4_000;

type CachedHealth = { projectId: SupabaseProjectConfig["id"]; at: number };

let healthCache: CachedHealth | null = null;
const clientCache = new Map<string, SupabaseClient<Database>>();

function makeClient(project: SupabaseProjectConfig): SupabaseClient<Database> {
  const existing = clientCache.get(project.id);
  if (existing) return existing;
  const client = createClient<Database>(project.url, project.publishableKey, {
    accessToken: async () => getSupabaseAccessToken(),
  });
  clientCache.set(project.id, client);
  return client;
}

async function probeProject(project: SupabaseProjectConfig): Promise<boolean> {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), HEALTH_TIMEOUT_MS);
  try {
    // Prefer light REST root; fall back to feed-api stats if REST blocked
    const rest = await fetch(`${project.url}/rest/v1/`, {
      method: "HEAD",
      headers: {
        apikey: project.publishableKey,
        Authorization: `Bearer ${project.publishableKey}`,
      },
      signal: ctrl.signal,
      cache: "no-store",
    });
    if (rest.ok || rest.status === 200 || rest.status === 400 || rest.status === 404) {
      return true;
    }
  } catch {
    /* try edge health next */
  } finally {
    clearTimeout(t);
  }

  const ctrl2 = new AbortController();
  const t2 = setTimeout(() => ctrl2.abort(), HEALTH_TIMEOUT_MS);
  try {
    const res = await fetch(`${project.url}/functions/v1/feed-api/stats`, {
      headers: {
        ...anonAuthHeaders(),
        apikey: project.publishableKey,
        Authorization: `Bearer ${project.publishableKey}`,
      },
      signal: ctrl2.signal,
      cache: "no-store",
    });
    return res.ok || res.status === 401 || res.status === 403;
  } catch {
    return false;
  } finally {
    clearTimeout(t2);
  }
}

/** Resolve healthy project (cached briefly). Falls back to primary config if all probes fail. */
export async function resolveHealthyProject(): Promise<SupabaseProjectConfig> {
  const projects = getSupabaseProjects();
  const cfg = getRuntimeConfig();
  if (projects.length === 0) {
    return {
      id: "primary",
      url: cfg.supabaseUrl,
      publishableKey: cfg.supabasePublishableKey,
    };
  }
  if (healthCache && Date.now() - healthCache.at < HEALTH_TTL_MS) {
    const hit = projects.find((p) => p.id === healthCache!.projectId);
    if (hit) return hit;
  }

  for (const project of projects) {
    if (await probeProject(project)) {
      healthCache = { projectId: project.id, at: Date.now() };
      if (project.id !== "primary" && import.meta.env.DEV) {
        console.warn(`[supabase-failover] using ${project.id} (${project.url})`);
      }
      return project;
    }
  }

  // Last resort: primary entry even if probe failed (surface real errors to UI)
  healthCache = { projectId: projects[0].id, at: Date.now() };
  return projects[0];
}

export async function getActiveSupabaseClient(): Promise<SupabaseClient<Database>> {
  return makeClient(await resolveHealthyProject());
}

/** Call an edge function on primary, then secondary on network/5xx failure. */
export async function fetchEdgeWithFailover(
  path: string,
  init: RequestInit = {},
): Promise<{ response: Response; project: SupabaseProjectConfig }> {
  const projects = getSupabaseProjects();
  const cfg = getRuntimeConfig();
  const list =
    projects.length > 0
      ? projects
      : [{ id: "primary" as const, url: cfg.supabaseUrl, publishableKey: cfg.supabasePublishableKey }];

  let lastError: unknown;
  for (const project of list) {
    const url = `${project.url}/functions/v1/${path.replace(/^\//, "")}`;
    const headers = new Headers(init.headers);
    if (!headers.has("apikey")) headers.set("apikey", project.publishableKey);
    if (!headers.has("Authorization")) {
      headers.set("Authorization", `Bearer ${project.publishableKey}`);
    }
    try {
      const response = await fetch(url, { ...init, headers, cache: "no-store" });
      if (response.ok || (response.status >= 400 && response.status < 500 && response.status !== 408)) {
        // 4xx (except timeout-ish) is app-level — don't fail over (wrong project won't help auth errors the same way,
        // but 503/502/network should). Keep 401/403 on this project.
        return { response, project };
      }
      if (response.status >= 500 || response.status === 408 || response.status === 429) {
        lastError = new Error(`${project.id} HTTP ${response.status}`);
        continue;
      }
      return { response, project };
    } catch (e) {
      lastError = e;
    }
  }
  throw lastError instanceof Error ? lastError : new Error("All Supabase projects unreachable");
}

export function invalidateSupabaseHealthCache(): void {
  healthCache = null;
}
