import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { resolveLabConfig, type RedTeamLabConfig } from "@/lib/redteam/lab";

async function fetchEdgeLabConfig(): Promise<Partial<RedTeamLabConfig> | null> {
  try {
    const { data, error } = await supabase.functions.invoke("redteam-lab-config");
    if (error || !data || data.error) return null;
    return data as Partial<RedTeamLabConfig>;
  } catch {
    return null;
  }
}

export function useRedTeamLabConfig() {
  return useQuery({
    queryKey: ["redteam", "lab-config"],
    queryFn: async () => {
      const edge = await fetchEdgeLabConfig();
      return resolveLabConfig(edge);
    },
    staleTime: 120_000,
    refetchInterval: 300_000,
  });
}

export type { RedTeamLabConfig };
