async function tableReachable(table: string): Promise<boolean> {
  const { error } = await supabase.from(table as "threat_items").select("id").limit(1);
  return !error;
}

async function labReachable(url: string | undefined): Promise<boolean> {
  if (!url) return false;
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 6000);
    const res = await fetch(url, { method: "GET", mode: "no-cors", signal: ctrl.signal });
    clearTimeout(t);
    void res;
    return true;
  } catch {
    return false;
  }
}

export async function checkRedTeamToolStatus(
  toolId: string,
  labConfig?: RedTeamLabConfig,
): Promise<RedTeamToolStatus> {
  switch (toolId) {
    case "portal":
      return (await tableReachable("redteam_engagements")) ? "online" : "offline";
    case "phishing":
      return (await tableReachable("phishing_campaigns")) ? "online" : "offline";
    case "attack":
    case "chain":
    case "brand":
      return "online";
    case "lab": {
      const labs = labConfig ?? resolveLabConfig();
      if (labs.mode === "free") {
        return "online"; // free workbench always available
      }
      const checks = await Promise.all([
        labReachable(labs.kaliUrl),
        labReachable(labs.targetUrl),
        labReachable(labs.desktopUrl),
        labReachable(labs.guacamoleUrl),
      ]);
      const up = checks.filter(Boolean).length;
      if (labs.source === "none" && !labs.labHost) return "offline";
      if (up >= 2) return "online";
      return up > 0 ? "degraded" : labs.labHost || labs.kaliUrl ? "degraded" : "offline";
    }
    case "ai-assessment":
    case "pentest-agent":
      return "online";
    default:
      return "offline";
  }
}

export async function fetchAllRedTeamToolStatuses(labConfig?: RedTeamLabConfig): Promise<Record<string, RedTeamToolStatus>> {
  const entries = await Promise.all(
    RED_TEAM_TOOLS.map(async (t) => [t.id, await checkRedTeamToolStatus(t.id, labConfig)] as const),
  );
  return Object.fromEntries(entries);
}
