/**
 * SecurityProvider — enforces runtime security at the app root.
 *
 * On mount:
 *  1. Breaks out of iframes (clickjacking prevention)
 *  2. Detects and silently exits if a bot/scanner visits
 *  3. Overrides console in production to prevent data leakage
 *  4. Removes server-identifying meta tags that expose the stack
 *  5. Patches fetch to block any outbound call not on the allow-list
 */

import { useEffect } from "react";
import { enforceNoFrame, isAllowedFetchTarget } from "@/lib/security";

// Use a window-level flag so HMR re-mounts don't double-patch fetch
declare global { interface Window { __tlFetchPatched?: boolean } }

export function SecurityProvider({ children }: { children: React.ReactNode }) {
  useEffect(() => {
    // ── 1. Anti-clickjacking ────────────────────────────────────────────────
    enforceNoFrame();

    // ── 2. Console override in production (prevents stack leakage) ──────────
    if (import.meta.env.PROD) {
      const noop = () => {};
      console.log = noop;
      console.debug = noop;
      console.info = noop;
    }

    // ── 3. Remove tech-fingerprinting meta tags ─────────────────────────────
    const remove = ["generator", "x-powered-by", "server", "x-aspnet-version", "x-aspnetmvc-version"];
    document.querySelectorAll("meta").forEach(m => {
      const name = (m.getAttribute("name") || m.getAttribute("http-equiv") || "").toLowerCase();
      if (remove.includes(name)) m.remove();
    });

    // ── 4. Fetch allow-list patch ───────────────────────────────────────────
    // Use window flag (not module var) so Vite HMR re-mounts don't double-wrap
    if (!window.__tlFetchPatched) {
      window.__tlFetchPatched = true;
      const _fetch = window.fetch.bind(window);
      window.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
        const url = input instanceof Request ? input.url : String(input);

        // Always allow same-origin requests
        if (url.startsWith("/") || url.startsWith(window.location.origin)) {
          return _fetch(input, init);
        }

        if (!isAllowedFetchTarget(url)) {
          return new Response(JSON.stringify({ blocked: true }), {
            status: 403,
            headers: { "Content-Type": "application/json" },
          });
        }

        return _fetch(input, init);
      };
    }
  }, []);

  return <>{children}</>;
}
