import { useQuery } from "@tanstack/react-query";
import {
  fetchCompanyLiveStats,
  fetchAIPipelineRows,
  fetchOnboardingStepsLive,
  fetchDivisionMetrics,
  checkPlatformHealth,
  type CompanyLiveStats,
  type AIPipelineRow,
  type OnboardingStepLive,
} from "@/lib/company-live-data";

export function useCompanyLiveStats() {
  return useQuery({
    queryKey: ["company", "live-stats"],
    queryFn: fetchCompanyLiveStats,
    staleTime: 30_000,
    refetchInterval: 60_000,
  });
}

export function useAIPipelineRows() {
  return useQuery({
    queryKey: ["company", "ai-pipeline"],
    queryFn: fetchAIPipelineRows,
    staleTime: 60_000,
    refetchInterval: 120_000,
  });
}

export function useOnboardingLive() {
  return useQuery({
    queryKey: ["company", "onboarding"],
    queryFn: fetchOnboardingStepsLive,
    staleTime: 30_000,
    refetchInterval: 60_000,
  });
}

export function useDivisionMetrics(divisionId: string) {
  return useQuery({
    queryKey: ["company", "division", divisionId],
    queryFn: () => fetchDivisionMetrics(divisionId),
    staleTime: 30_000,
    refetchInterval: 60_000,
  });
}

export function usePlatformHealth() {
  return useQuery({
    queryKey: ["company", "health"],
    queryFn: checkPlatformHealth,
    staleTime: 30_000,
    refetchInterval: 60_000,
  });
}

export type { CompanyLiveStats, AIPipelineRow, OnboardingStepLive };
