/** Free-tier limit thresholds — keep site running within caps. */

export const LIMITS = {
  supabase: { hardMb: 500, warnMb: 350, targetMb: 300 },
  turso: { hardGb: 9, warnGb: 7, maxItems: 50000 },
  upstash: { cmdsPerDay: 10000, warnPct: 0.85 },
  gist: { shardSoftBytes: 900_000, maxFiles: 280 },
  feeds: { supabaseRetentionDays: 7, tursoRetentionDays: 30, staleMinutes: 20 },
  githubPages: { bandwidthGbMonth: 100 },
  cloudflareWorkers: { requestsPerDay: 100_000 },
} as const;

export type ServiceHealth = "ok" | "warn" | "critical" | "unknown";

export type LimitCheck = {
  service: string;
  status: ServiceHealth;
  message: string;
  action?: string;
};

export function worstStatus(checks: LimitCheck[]): ServiceHealth {
  if (checks.some((c) => c.status === "critical")) return "critical";
  if (checks.some((c) => c.status === "warn")) return "warn";
  if (checks.every((c) => c.status === "unknown")) return "unknown";
  return "ok";
}
