import { Route } from "react-router-dom";
import { AdminOnlyRoute } from "@/components/AdminOnlyRoute";
import { WorkspaceShell } from "@/components/workspace/WorkspaceShell";
import { getAllWorkspaceConfigs } from "@/config/workspaces";

type Props = {
  routeSkeleton: React.ReactNode;
  statusIndicator?: React.ReactNode;
};

/** Returns <Route> elements — must be inlined inside <Routes>, not wrapped in a component. */
export function workspaceRouteElements({ routeSkeleton, statusIndicator }: Props) {
  return getAllWorkspaceConfigs().map((config) => {
    const pathPrefix = config.root.replace(/^\//, "");
    const shell = (
      <WorkspaceShell
        config={config}
        routeSkeleton={routeSkeleton}
        statusIndicator={statusIndicator}
      />
    );
    return (
      <Route
        key={config.divisionId}
        path={`${pathPrefix}/*`}
        element={config.adminOnly ? <AdminOnlyRoute>{shell}</AdminOnlyRoute> : shell}
      />
    );
  });
}
