import { NavLink } from "@/components/NavLink";
import { useUser, signOut } from "@/lib/auth-adapter";
import { useRole } from "@/contexts/RoleContext";
import { LogOut } from "lucide-react";
import {
  Sidebar, SidebarContent, SidebarGroup, SidebarGroupContent,
  SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton,
  SidebarMenuItem, SidebarFooter, useSidebar,
} from "@/components/ui/sidebar";
import type { WorkspaceConfig, WorkspaceNavItem } from "@/config/workspaces";

type Props = { config: WorkspaceConfig };

function NavGroup({
  label, items, collapsed, isAdmin, theme, workspaceRoot,
}: {
  label: string;
  items: WorkspaceNavItem[];
  collapsed: boolean;
  isAdmin: boolean;
  theme: WorkspaceConfig["theme"];
  workspaceRoot: string;
}) {
  const visible = items.filter((item) => !item.adminOnly || isAdmin);
  if (visible.length === 0) return null;

  return (
    <SidebarGroup className="px-2 py-1">
      {!collapsed && (
        <SidebarGroupLabel
          className="mb-1 px-2.5 text-[10px] font-semibold uppercase tracking-widest"
          style={{ color: `rgba(${theme.accentRgb},0.55)` }}
        >
          {label}
        </SidebarGroupLabel>
      )}
      <SidebarGroupContent>
        <SidebarMenu className="gap-0.5">
          {visible.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton asChild>
                <NavLink
                  to={item.url}
                  end={item.url === workspaceRoot}
                  className="group flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm transition-all duration-150 text-slate-400 hover:text-slate-100 hover:bg-white/[0.05] workspace-nav-link"
                  activeClassName="workspace-nav-active font-medium"
                  data-accent={theme.accentRgb}
                >
                  <item.icon className="h-4 w-4 shrink-0 opacity-70 group-hover:opacity-100 transition-opacity" />
                  {!collapsed && <span className="flex-1 truncate">{item.title}</span>}
                  {!collapsed && item.badge && (
                    <span
                      className="ml-auto text-[9px] font-bold px-1.5 py-0.5 rounded border"
                      style={{
                        borderColor: `rgba(${theme.accentRgb},0.3)`,
                        background: `rgba(${theme.accentRgb},0.12)`,
                        color: theme.accentLight,
                      }}
                    >
                      {item.badge}
                    </span>
                  )}
                </NavLink>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

export function WorkspaceSidebar({ config }: Props) {
  const { state } = useSidebar();
  const collapsed = state === "collapsed";
  const { user } = useUser();
  const userEmail = user?.primaryEmailAddress?.emailAddress ?? "";
  const { isAdmin } = useRole();
  const { theme } = config;
  const Icon = config.icon;

  const initials = userEmail ? userEmail.slice(0, 2).toUpperCase() : "?";

  return (
    <Sidebar
      collapsible="icon"
      className="border-r-0 sidebar-bg-premium workspace-sidebar"
      style={{
        borderRight: `1px solid rgba(${theme.accentRgb},0.12)`,
        ["--ws-accent-rgb" as string]: theme.accentRgb,
      }}
      data-workspace-accent={theme.accentRgb}
    >
      <SidebarHeader className="px-3 py-4" style={{ borderBottom: `1px solid rgba(${theme.accentRgb},0.12)` }}>
        <NavLink to={config.root} className="flex items-center gap-3 rounded-lg hover:opacity-90 transition-opacity">
          <div
            className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-xl"
            style={{
              background: `linear-gradient(135deg, rgba(${theme.accentRgb},0.25), rgba(${theme.accentRgb},0.15))`,
              border: `1px solid rgba(${theme.accentRgb},0.35)`,
              boxShadow: `0 0 16px rgba(${theme.accentRgb},0.15)`,
            }}
          >
            <Icon className="h-5 w-5" style={{ color: theme.accentLight }} />
            <span
              className="absolute -top-0.5 -right-0.5 h-2.5 w-2.5 rounded-full border-2 border-[#050a14] animate-pulse"
              style={{ background: theme.accent }}
            />
          </div>
          {!collapsed && (
            <div className="flex flex-col min-w-0">
              <span
                className="text-sm font-bold tracking-tight truncate"
                style={{
                  background: `linear-gradient(135deg, ${theme.gradientFrom}, ${theme.gradientTo})`,
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                }}
              >
                {config.title.split(" ")[0]}
              </span>
              <span className="text-[9px] uppercase tracking-[0.18em] text-slate-600 truncate">
                {config.subtitle}
              </span>
            </div>
          )}
        </NavLink>
      </SidebarHeader>

      <SidebarContent className="overflow-y-auto scrollbar-thin py-2">
        {config.navGroups.map((group) => (
          <NavGroup
            key={group.label}
            label={group.label}
            items={group.items}
            collapsed={collapsed}
            isAdmin={isAdmin}
            theme={theme}
            workspaceRoot={config.root}
          />
        ))}
      </SidebarContent>

      <SidebarFooter style={{ borderTop: `1px solid rgba(${theme.accentRgb},0.12)` }}>
        <div className={`px-2 pb-3 pt-2 ${collapsed ? "flex justify-center" : ""}`}>
          {collapsed ? (
            <button
              type="button"
              onClick={() => signOut()}
              title={`Sign out ${userEmail}`}
              className="flex h-9 w-9 items-center justify-center rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-500/10 transition-all"
            >
              <LogOut className="h-4 w-4" />
            </button>
          ) : (
            <div
              className="flex items-center gap-2.5 rounded-xl px-3 py-2.5"
              style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.07)" }}
            >
              <div
                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-[11px] font-bold"
                style={{
                  color: theme.accentLight,
                  background: `linear-gradient(135deg, rgba(${theme.accentRgb},0.2), rgba(${theme.accentRgb},0.1))`,
                  border: `1px solid rgba(${theme.accentRgb},0.25)`,
                }}
              >
                {initials}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[11px] font-medium text-slate-300 truncate">{userEmail}</p>
                <p className="text-[10px] text-slate-600 truncate">{config.title}</p>
              </div>
              <button
                type="button"
                onClick={() => signOut()}
                title="Sign out"
                className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-600 hover:text-red-400 hover:bg-red-500/10 transition-all"
              >
                <LogOut className="h-3.5 w-3.5" />
              </button>
            </div>
          )}
        </div>
      </SidebarFooter>
    </Sidebar>
  );
}
