// ── Collapsible nav item ───────────────────────────────────────────────────────
function CollapsibleItem({
  item, collapsed, openKey, setOpenKey,
}: { item: NavItem; collapsed: boolean; openKey: string; setOpenKey: (k: string) => void }) {
  const open = openKey === item.title;
  const hasSub = !!item.sub?.length;
  const badgeClass = item.badgeColor ? BADGE_COLORS[item.badgeColor] ?? BADGE_COLORS.cyan : BADGE_COLORS.cyan;

  if (!hasSub || collapsed) {
    return (
      <SidebarMenuItem>
        <SidebarMenuButton asChild>
          <NavLink
            to={item.url}
            end={item.url === "/"}
            className="group flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm transition-all duration-150 text-slate-400 hover:text-slate-100 hover:bg-white/[0.05]"
            activeClassName="nav-item-active-glow text-cyan-300 font-medium"
          >
            <item.icon className="h-4 w-4 shrink-0 opacity-70 group-hover:opacity-100 transition-opacity" />
            {!collapsed && <span className="flex-1 truncate">{item.title}</span>}
            {!collapsed && item.badge && (
              <span className={`ml-auto text-[9px] font-bold px-1.5 py-0.5 rounded border ${badgeClass}`}>
                {item.badge}
              </span>
            )}
          </NavLink>
        </SidebarMenuButton>
      </SidebarMenuItem>
    );
  }

  return (
    <SidebarMenuItem>
      <button
        onClick={() => setOpenKey(open ? "" : item.title)}
        className="group flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm text-slate-400 hover:text-slate-100 hover:bg-white/[0.05] transition-all duration-150"
      >
        <item.icon className="h-4 w-4 shrink-0 opacity-70 group-hover:opacity-100 transition-opacity" />
        <span className="flex-1 text-left truncate">{item.title}</span>
        {open
          ? <ChevronDown className="h-3.5 w-3.5 shrink-0 text-slate-600" />
          : <ChevronRight className="h-3.5 w-3.5 shrink-0 text-slate-600" />}
      </button>
      {open && (
        <div className="mt-0.5 ml-4 border-l border-cyan-500/15 pl-2 flex flex-col gap-0.5">
          {item.sub!.map((s) => (
            <NavLink
              key={s.title}
              to={s.url}
              className="flex items-center gap-1.5 rounded-md px-2 py-1.5 text-xs text-slate-500 hover:text-slate-200 hover:bg-white/[0.04] transition-all duration-150"
              activeClassName="text-cyan-400 bg-cyan-500/10 font-medium"
            >
              <s.icon className="h-3 w-3 shrink-0" />
              <span className="truncate">{s.title}</span>
            </NavLink>
          ))}
        </div>
      )}
    </SidebarMenuItem>
  );
}

const GROUP_PATHS: Record<string, string[]> = {
  "Vulnerabilities": ["/vulns", "/cve"],
  "Ransomware":      ["/ransomware"],
  "Malware":         ["/malware", "/iocs"],
  "MITRE ATT&CK":    ["/attack", "/threat-framework"],
  // Attack Surface removed per product decision
};

function groupForPath(pathname: string): string {
  for (const [group, paths] of Object.entries(GROUP_PATHS)) {
    if (paths.some(p => pathname === p || pathname.startsWith(p + "?") || pathname.startsWith(p + "/"))) return group;
  }
  return "";
}

const GROUP_ACCENT: Record<string, string> = {
  "Home":       "text-slate-500/70",
  "Threats":    "text-red-400/70",
  "Operations": "text-orange-400/70",
  "Analysis":   "text-violet-400/70",
};

function NavGroup({
  label, items, collapsed, openKey, setOpenKey, isAdmin,
}: { label: string; items: NavItem[]; collapsed: boolean; openKey: string; setOpenKey: (k: string) => void; isAdmin: boolean }) {
  const visible = items.filter((item) => !item.adminOnly || isAdmin);
  if (visible.length === 0) return null;
  const accentColor = GROUP_ACCENT[label] ?? "text-slate-500/70";
  return (
    <SidebarGroup className="px-2 py-1">
      {!collapsed && (
        <SidebarGroupLabel className={`mb-1 px-2.5 text-[10px] font-semibold uppercase tracking-widest ${accentColor}`}>
          {label}
        </SidebarGroupLabel>
      )}
      <SidebarGroupContent>
        <SidebarMenu className="gap-0.5">
          {visible.map((item) => (
            <CollapsibleItem
              key={item.title} item={item} collapsed={collapsed}
              openKey={openKey} setOpenKey={setOpenKey}
            />
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

// ── Live Status Strip ─────────────────────────────────────────────────────────
function LiveStatus() {
  const [count, setCount] = useState<number | null>(null);
  const [critCount, setCritCount] = useState<number>(0);

  useEffect(() => {
    let cancelled = false;
    async function fetchCounts() {
      const stats = await getFeedBackendStats();
      if (stats) {
        if (!cancelled) {
          setCount(stats.item_count ?? 0);
          setCritCount(stats.critical_count ?? 0);
        }
        return;
      }
      const [{ count: total }, { count: crit }] = await Promise.all([
        supabase.from("threat_items").select("id", { count: "exact", head: true }),
        supabase.from("threat_items").select("id", { count: "exact", head: true }).eq("severity", "critical"),
      ]);
      if (!cancelled) { setCount(total ?? null); setCritCount(crit ?? 0); }
    }
    fetchCounts();
    const interval = setInterval(fetchCounts, 60_000);
    return () => { cancelled = true; clearInterval(interval); };
  }, []);

  return (
    <div className="px-3 py-2 mx-2 mb-1 rounded-lg bg-emerald-500/5 border border-emerald-500/10">
      <div className="flex items-center gap-2 text-[10px] text-slate-500">
        <span className="relative flex h-2 w-2 shrink-0">
          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-50" />
          <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500" />
        </span>
        <span className="flex-1">
          {count === null
            ? "Connecting…"
            : <><span className="text-emerald-400 font-semibold">{count.toLocaleString()}</span> threats · <span className="text-red-400 font-semibold">{critCount}</span> critical</>}
        </span>
      </div>
    </div>
  );
}

