/**
 * Cloud-first Red Team lab URL resolution.
 * Priority: Supabase edge config → individual VITE_* → VITE_REDTEAM_LAB_HOST paths → empty (never fake localhost in prod).
 */
export type RedTeamLabConfig = {
  kaliUrl: string;
  targetUrl: string;
  desktopUrl: string;
  guacamoleUrl: string;
  windowsKvmUrl: string;
  juiceShopUrl: string;
  dvwaUrl: string;
  flyLabUrl: string;
  labHost: string;
  mode: "hosted" | "free" | "local";
  source: "edge" | "env" | "derived" | "none";
};

export type LabMachineId = "kali" | "target" | "desktop" | "guacamole" | "windows-kvm";

export type LabMachine = {
  id: LabMachineId;
  name: string;
  os: string;
  url: string;
  description: string;
  defaultUser: string;
  embedType: "terminal" | "desktop" | "portal";
};

function readEnv(name: string): string {
  const v = import.meta.env[name];
  return typeof v === "string" ? v.trim() : "";
}

function isLocalUrl(url: string): boolean {
  return /localhost|127\.0\.0\.1|^http:\/\/0\.0\.0\.0/i.test(url);
}

function isProdBuild(): boolean {
  return import.meta.env.PROD === true;
}

/** Build path-based URLs from a single cloud lab host (Caddy reverse proxy). */
export function labUrlsFromHost(
  host: string,
): Pick<
  RedTeamLabConfig,
  "kaliUrl" | "targetUrl" | "desktopUrl" | "guacamoleUrl" | "windowsKvmUrl" | "juiceShopUrl" | "dvwaUrl"
> {
  const base = host.replace(/\/$/, "");
  return {
    kaliUrl: `${base}/kali/`,
    targetUrl: `${base}/target/`,
    desktopUrl: `${base}/desktop/`,
    guacamoleUrl: `${base}/guacamole/`,
    windowsKvmUrl: `${base}/windows/`,
    juiceShopUrl: `${base}/juice-shop/`,
    dvwaUrl: `${base}/dvwa/`,
  };
}

export function resolveLabConfig(edge?: Partial<RedTeamLabConfig> | null): RedTeamLabConfig {
  const labHost =
    edge?.labHost ||
    readEnv("VITE_REDTEAM_LAB_HOST") ||
    "";

  const individual = {
    kaliUrl: readEnv("VITE_REDTEAM_KALI_URL"),
    targetUrl: readEnv("VITE_REDTEAM_TARGET_URL"),
    desktopUrl: readEnv("VITE_REDTEAM_DESKTOP_URL") || readEnv("VITE_REDTEAM_WINDOWS_URL"),
    guacamoleUrl: readEnv("VITE_REDTEAM_GUACAMOLE_URL"),
    windowsKvmUrl: readEnv("VITE_REDTEAM_WINDOWS_KVM_URL"),
    juiceShopUrl: readEnv("VITE_REDTEAM_JUICE_SHOP_URL"),
    dvwaUrl: readEnv("VITE_REDTEAM_DVWA_URL"),
  };

  const bountyDefaults = {
    juiceShopUrl: individual.juiceShopUrl || "http://localhost:3001",
    dvwaUrl: individual.dvwaUrl || "http://localhost:8082",
  };

  // Edge function (Supabase secrets) — live cloud config without redeploy
  if (edge?.kaliUrl || edge?.labHost || edge?.flyLabUrl) {
    const derived = edge.labHost ? labUrlsFromHost(edge.labHost) : {};
    return {
      labHost: edge.labHost || labHost,
      flyLabUrl: edge.flyLabUrl || readEnv("VITE_REDTEAM_FLY_LAB_URL"),
      kaliUrl: edge.kaliUrl || derived.kaliUrl || individual.kaliUrl || edge.flyLabUrl || "",
      targetUrl: edge.targetUrl || derived.targetUrl || individual.targetUrl,
      desktopUrl: edge.desktopUrl || derived.desktopUrl || individual.desktopUrl,
      guacamoleUrl: edge.guacamoleUrl || derived.guacamoleUrl || individual.guacamoleUrl,
      windowsKvmUrl: edge.windowsKvmUrl || derived.windowsKvmUrl || individual.windowsKvmUrl,
      juiceShopUrl: edge.juiceShopUrl || derived.juiceShopUrl || bountyDefaults.juiceShopUrl,
      dvwaUrl: edge.dvwaUrl || derived.dvwaUrl || bountyDefaults.dvwaUrl,
      mode: edge.mode === "hosted" ? "hosted" : edge.flyLabUrl || readEnv("VITE_REDTEAM_FLY_LAB_URL") ? "free" : "free",
      source: "edge",
    };
  }

  const flyLabUrl = readEnv("VITE_REDTEAM_FLY_LAB_URL");

  // Explicit per-service env vars (CI / Cloudflare build)
  if (individual.kaliUrl || individual.targetUrl || individual.desktopUrl || individual.guacamoleUrl || flyLabUrl) {
    const filtered = isProdBuild()
      ? Object.fromEntries(Object.entries(individual).filter(([, v]) => v && !isLocalUrl(v)))
      : individual;
    if (Object.values(filtered).some(Boolean) || flyLabUrl) {
      return {
        labHost,
        flyLabUrl,
        kaliUrl: filtered.kaliUrl || flyLabUrl || "",
        targetUrl: filtered.targetUrl || "",
        desktopUrl: filtered.desktopUrl || "",
        guacamoleUrl: filtered.guacamoleUrl || "",
        windowsKvmUrl: filtered.windowsKvmUrl || "",
        juiceShopUrl: isProdBuild() && isLocalUrl(bountyDefaults.juiceShopUrl) ? "" : bountyDefaults.juiceShopUrl,
        dvwaUrl: isProdBuild() && isLocalUrl(bountyDefaults.dvwaUrl) ? "" : bountyDefaults.dvwaUrl,
        mode: labHost && !isLocalUrl(labHost) ? "hosted" : flyLabUrl ? "free" : "free",
        source: "env",
      };
    }
  }

  // Single cloud host → path routing
  if (labHost && !isLocalUrl(labHost)) {
    return { labHost, flyLabUrl, ...labUrlsFromHost(labHost), mode: "hosted", source: "derived" };
  }

  // Free tier: Fly.io terminal only (no paid VPS)
  if (flyLabUrl && !isLocalUrl(flyLabUrl)) {
    return {
      labHost: "",
      flyLabUrl,
      kaliUrl: flyLabUrl,
      targetUrl: "",
      desktopUrl: "",
      guacamoleUrl: "",
      windowsKvmUrl: "",
      juiceShopUrl: "",
      dvwaUrl: "",
      mode: "free",
      source: "env",
    };
  }

  // Dev-only localhost fallback
  if (!isProdBuild() && labHost && isLocalUrl(labHost)) {
    return { labHost, flyLabUrl, ...labUrlsFromHost(labHost), mode: "local", source: "derived" };
  }

  if (!isProdBuild()) {
    return {
      labHost: "http://localhost:7680",
      flyLabUrl: flyLabUrl || "",
      kaliUrl: readEnv("VITE_REDTEAM_KALI_URL") || flyLabUrl || "http://localhost:7681",
      targetUrl: readEnv("VITE_REDTEAM_TARGET_URL") || "http://localhost:7682",
      desktopUrl: readEnv("VITE_REDTEAM_DESKTOP_URL") || "http://localhost:3000",
      guacamoleUrl: readEnv("VITE_REDTEAM_GUACAMOLE_URL") || "http://localhost:8081/guacamole",
      windowsKvmUrl: readEnv("VITE_REDTEAM_WINDOWS_KVM_URL") || "http://localhost:8006",
      juiceShopUrl: bountyDefaults.juiceShopUrl,
      dvwaUrl: bountyDefaults.dvwaUrl,
      mode: "local",
      source: "env",
    };
  }

  // Production with no paid lab → free workbench mode (always available)
  return {
    labHost: "",
    flyLabUrl: "",
    kaliUrl: "",
    targetUrl: "",
    desktopUrl: "",
    guacamoleUrl: "",
    windowsKvmUrl: "",
    juiceShopUrl: "",
    dvwaUrl: "",
    mode: "free",
    source: "none",
  };
}

/** @deprecated use resolveLabConfig via useRedTeamLabConfig hook */
export function getRedTeamLabConfig(): RedTeamLabConfig {
  return resolveLabConfig();
}

